import express from 'express';
import { getProjects, getProjectById, createProject, updateProject, deleteProject } from '../controllers/projectController';

const router = express.Router();

// Route to get all projects
router.get('/projects', getProjects);

// Route to get a specific project by ID
router.get('/projects/:id', getProjectById);

// Route to create a new project
router.post('/projects', createProject);

// Route to update an existing project
router.put('/projects/:id', updateProject);

// Route to delete a project
router.delete('/projects/:id', deleteProject);

export default router;

import { Request, Response } from 'express';
import { ProjectService } from '../services/projectService';

class ProjectController {
  private projectService: ProjectService;

  constructor() {
    this.projectService = new ProjectService();
  }

  public async getAllProjects(req: Request, res: Response): Promise<Response> {
    try {
      const projects = await this.projectService.getAllProjects();
      return res.status(200).json(projects);
    } catch (error) {
      return res.status(500).json({ message: 'Error retrieving projects', error });
    }
  }

  public async getProjectById(req: Request, res: Response): Promise<Response> {
    const { id } = req.params;
    try {
      const project = await this.projectService.getProjectById(id);
      if (!project) {
        return res.status(404).json({ message: 'Project not found' });
      }
      return res.status(200).json(project);
    } catch (error) {
      return res.status(500).json({ message: 'Error retrieving project', error });
    }
  }

  public async createProject(req: Request, res: Response): Promise<Response> {
    try {
      const newProject = await this.projectService.createProject(req.body);
      return res.status(201).json(newProject);
    } catch (error) {
      return res.status(400).json({ message: 'Error creating project', error });
    }
  }

  public async updateProject(req: Request, res: Response): Promise<Response> {
    const { id } = req.params;
    try {
      const updatedProject = await this.projectService.updateProject(id, req.body);
      if (!updatedProject) {
        return res.status(404).json({ message: 'Project not found' });
      }
      return res.status(200).json(updatedProject);
    } catch (error) {
      return res.status(400).json({ message: 'Error updating project', error });
    }
  }

  public async deleteProject(req: Request, res: Response): Promise<Response> {
    const { id } = req.params;
    try {
      const deleted = await this.projectService.deleteProject(id);
      if (!deleted) {
        return res.status(404).json({ message: 'Project not found' });
      }
      return res.status(204).send();
    } catch (error) {
      return res.status(500).json({ message: 'Error deleting project', error });
    }
  }
}

export default new ProjectController();

import { Request, Response } from 'express';
import { ProjectRepository } from '../repositories/projectRepository';
import { Project } from '../models/project';

class ProjectService {
  private projectRepository: ProjectRepository;

  constructor() {
    this.projectRepository = new ProjectRepository();
  }

  public async createProject(req: Request, res: Response): Promise<Response> {
    try {
      const { name, description, startDate, endDate } = req.body;
      if (!name || !startDate || !endDate) {
        return res.status(400).json({ message: 'Name, start date, and end date are required.' });
      }

      const newProject = new Project(name, description, new Date(startDate), new Date(endDate));
      const savedProject = await this.projectRepository.save(newProject);

      return res.status(201).json(savedProject);
    } catch (error) {
      return res.status(500).json({ message: 'Internal server error', error });
    }
  }

  public async getProjectById(req: Request, res: Response): Promise<Response> {
    try {
      const { id } = req.params;
      const project = await this.projectRepository.findById(id);

      if (!project) {
        return res.status(404).json({ message: 'Project not found' });
      }

      return res.status(200).json(project);
    } catch (error) {
      return res.status(500).json({ message: 'Internal server error', error });
    }
  }

  public async updateProject(req: Request, res: Response): Promise<Response> {
    try {
      const { id } = req.params;
      const { name, description, startDate, endDate } = req.body;

      const project = await this.projectRepository.findById(id);
      if (!project) {
        return res.status(404).json({ message: 'Project not found' });
      }

      project.name = name || project.name;
      project.description = description || project.description;
      project.startDate = startDate ? new Date(startDate) : project.startDate;
      project.endDate = endDate ? new Date(endDate) : project.endDate;

      const updatedProject = await this.projectRepository.save(project);

      return res.status(200).json(updatedProject);
    } catch (error) {
      return res.status(500).json({ message: 'Internal server error', error });
    }
  }

  public async deleteProject(req: Request, res: Response): Promise<Response> {
    try {
      const { id } = req.params;
      const project = await this.projectRepository.findById(id);

      if (!project) {
        return res.status(404).json({ message: 'Project not found' });
      }

      await this.projectRepository.delete(id);

      return res.status(204).send();
    } catch (error) {
      return res.status(500).json({ message: 'Internal server error', error });
    }
  }
}

export default new ProjectService();

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

const authMiddleware = (req: Request, res: Response, next: NextFunction) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ message: 'Access denied. No token provided.' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET as string);
    req.user = decoded;
    next();
  } catch (ex) {
    res.status(400).json({ message: 'Invalid token.' });
  }
};

export default authMiddleware;

import { Model, DataTypes } from 'sequelize';
import { sequelize } from '../database';

class Project extends Model {
  public id!: number;
  public name!: string;
  public description!: string;
  public startDate!: Date;
  public endDate!: Date;
  public status!: string;
  public createdAt!: Date;
  public updatedAt!: Date;
}

Project.init(
  {
    id: {
      type: DataTypes.INTEGER,
      autoIncrement: true,
      primaryKey: true,
    },
    name: {
      type: DataTypes.STRING,
      allowNull: false,
    },
    description: {
      type: DataTypes.TEXT,
      allowNull: true,
    },
    startDate: {
      type: DataTypes.DATE,
      allowNull: false,
    },
    endDate: {
      type: DataTypes.DATE,
      allowNull: false,
    },
    status: {
      type: DataTypes.STRING,
      allowNull: false,
      validate: {
        isIn: [['planned', 'in-progress', 'completed', 'on-hold']],
      },
    },
    createdAt: {
      type: DataTypes.DATE,
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
    updatedAt: {
      type: DataTypes.DATE,
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
  },
  {
    sequelize,
    tableName: 'projects',
  }
);

export default Project;

import { Pool } from 'pg';
import { Project } from '../models/Project';

class ProjectRepository {
  private pool: Pool;

  constructor() {
    this.pool = new Pool({
      user: process.env.DB_USER,
      host: process.env.DB_HOST,
      database: process.env.DB_NAME,
      password: process.env.DB_PASSWORD,
      port: parseInt(process.env.DB_PORT || '5432', 10),
    });
  }

  async getAllProjects(): Promise<Project[]> {
    const result = await this.pool.query('SELECT * FROM projects');
    return result.rows;
  }

  async getProjectById(id: number): Promise<Project | null> {
    const result = await this.pool.query('SELECT * FROM projects WHERE id = $1', [id]);
    return result.rows[0] || null;
  }

  async createProject(project: Project): Promise<Project> {
    const result = await this.pool.query(
      'INSERT INTO projects (name, description, start_date, end_date) VALUES ($1, $2, $3, $4) RETURNING *',
      [project.name, project.description, project.start_date, project.end_date]
    );
    return result.rows[0];
  }

  async updateProject(id: number, project: Partial<Project>): Promise<Project | null> {
    const fields = Object.keys(project);
    const values = Object.values(project);
    const setClause = fields.map((field, index) => `${field} = $${index + 1}`).join(', ');
    const result = await this.pool.query(
      `UPDATE projects SET ${setClause} WHERE id = $${fields.length + 1} RETURNING *`,
      [...values, id]
    );
    return result.rows[0] || null;
  }

  async deleteProject(id: number): Promise<boolean> {
    const result = await this.pool.query('DELETE FROM projects WHERE id = $1', [id]);
    return result.rowCount > 0;
  }
}

export default new ProjectRepository();

import { createLogger, format, transports } from 'winston';

const logger = createLogger({
  level: 'info',
  format: format.combine(
    format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    format.errors({ stack: true }),
    format.splat(),
    format.json()
  ),
  defaultMeta: { service: 'user-service' },
  transports: [
    new transports.Console({
      format: format.combine(
        format.colorize(),
        format.simple()
      )
    }),
    new transports.File({ filename: 'logs/error.log', level: 'error' }),
    new transports.File({ filename: 'logs/combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new transports.Console({
    format: format.simple()
  }));
}

export default logger;

import { describe, it, expect, beforeEach } from 'vitest';
import { ProjectService } from '../src/services/projectService';
import { ProjectRepository } from '../src/repositories/projectRepository';
import { Project } from '../src/models/project';

// Mocking the ProjectRepository
const mockProjectRepository = {
  findById: jest.fn(),
  create: jest.fn(),
  update: jest.fn(),
  delete: jest.fn(),
};

// Initialize the ProjectService with the mocked repository
const projectService = new ProjectService(mockProjectRepository);

// Sample project data for testing
const sampleProject = new Project({
  id: 1,
  name: 'Test Project',
  description: 'A project for testing purposes',
  startDate: new Date('2023-01-01'),
  endDate: new Date('2023-02-28'),
  status: 'active',
});

describe('ProjectService', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('getProjectById', () => {
    it('should return a project when found', async () => {
      mockProjectRepository.findById.mockResolvedValue(sampleProject);

      const project = await projectService.getProjectById(1);

      expect(project).toEqual(sampleProject);
      expect(mockProjectRepository.findById).toHaveBeenCalledWith(1);
    });

    it('should throw an error when project is not found', async () => {
      mockProjectRepository.findById.mockResolvedValue(null);

      await expect(projectService.getProjectById(2)).rejects.toThrow('Project not found');
      expect(mockProjectRepository.findById).toHaveBeenCalledWith(2);
    });
  });

  describe('createProject', () => {
    it('should create and return a new project', async () => {
      mockProjectRepository.create.mockResolvedValue(sampleProject);

      const newProject = await projectService.createProject(sampleProject);

      expect(newProject).toEqual(sampleProject);
      expect(mockProjectRepository.create).toHaveBeenCalledWith(sampleProject);
    });
  });

  describe('updateProject', () => {
    it('should update and return the updated project', async () => {
      const updatedProject = { ...sampleProject, name: 'Updated Project' };
      mockProjectRepository.update.mockResolvedValue(updatedProject);

      const result = await projectService.updateProject(1, updatedProject);

      expect(result).toEqual(updatedProject);
      expect(mockProjectRepository.update).toHaveBeenCalledWith(1, updatedProject);
    });
  });

  describe('deleteProject', () => {
    it('should delete the project and return true', async () => {
      mockProjectRepository.delete.mockResolvedValue(true);

      const result = await projectService.deleteProject(1);

      expect(result).toBe(true);
      expect(mockProjectRepository.delete).toHaveBeenCalledWith(1);
    });
  });
});

