import React from 'react';

interface ReleaseDetailsProps {
  releaseId: string;
}

interface Release {
  id: string;
  version: string;
  date: string;
  description: string;
  features: string[];
  bugsFixed: string[];
}

const ReleaseDetails: React.FC<ReleaseDetailsProps> = ({ releaseId }) => {
  const [release, setRelease] = React.useState<Release | null>(null);
  const [loading, setLoading] = React.useState<boolean>(true);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    const fetchReleaseDetails = async () => {
      try {
        const response = await fetch(`/api/releases/${releaseId}`);
        if (!response.ok) {
          throw new Error('Failed to fetch release details');
        }
        const data: Release = await response.json();
        setRelease(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchReleaseDetails();
  }, [releaseId]);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  if (!release) {
    return <div>No release details available.</div>;
  }

  return (
    <div>
      <h1>Release {release.version}</h1>
