import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { ProjectService } from '../services/ProjectService';
import { CreateProjectDTO, UpdateProjectDTO } from '../dtos/ProjectDTOs';

export class ProjectController {
  private projectService: ProjectService;

  constructor(projectService: ProjectService) {
    this.projectService = projectService;
  }

  async createProject(req: FastifyRequest<{ Body: CreateProjectDTO }>, reply: FastifyReply) {
    try {
      const project = await this.projectService.createProject(req.body);
      reply.status(201).send(project);
    } catch (error) {
      reply.status(400).send({ error: error.message });
    }
  }

  async getProject(req: FastifyRequest<{ Params: { id: string } }>, reply: FastifyReply) {
    try {
      const project = await this.projectService.getProjectById(req.params.id);
      if (project) {
        reply.send(project);
      } else {
        reply.status(404).send({ error: 'Project not found' });
      }
    } catch (error) {
      reply.status(500).send({ error: error.message });
    }
  }

  async updateProject(req: FastifyRequest<{ Params: { id: string }, Body: UpdateProjectDTO }>, reply: FastifyReply) {
    try {
      const updatedProject = await this.projectService.updateProject(req.params.id, req.body);
      if (updatedProject) {
        reply.send(updatedProject);
      } else {
        reply.status(404).send({ error: 'Project not found' });
      }
    } catch (error) {
      reply.status(400).send({ error: error.message });
    }
  }

  async deleteProject(req: FastifyRequest<{ Params: { id: string } }>, reply: FastifyReply) {
    try {
      const success = await this.projectService.deleteProject(req.params.id);
      if (success) {
        reply.status(204).send();
      } else {
        reply.status(404).send({ error: 'Project not found' });
      }
    } catch (error) {
      reply.status(500).send({ error: error.message });
    }
  }

  async listProjects(req: FastifyRequest, reply: FastifyReply) {
    try {
      const projects = await this.projectService.listProjects();
      reply.send(projects);
    } catch (error) {
      reply.status(500).send({ error: error.message });
    }
  }
}

export default function registerProjectRoutes(fastify: FastifyInstance, projectService: ProjectService) {
  const controller = new ProjectController(projectService);

  fastify.post('/projects', controller.createProject.bind(controller));
  fastify.get('/projects/:id', controller.getProject.bind(controller));
  fastify.put('/projects/:id', controller.updateProject.bind(controller));
  fastify.delete('/projects/:id', controller.deleteProject.bind(controller));
  fastify.get('/projects', controller.listProjects.bind(controller));
}

