import { FastifyInstance } from 'fastify';
import { Client } from 'pg';

interface Project {
  id: number;
  name: string;
  description: string;
  startDate: Date;
  endDate: Date;
}

class ProjectService {
  private dbClient: Client;

  constructor(dbClient: Client) {
    this.dbClient = dbClient;
  }

  async getProjectById(id: number): Promise<Project | null> {
    try {
      const result = await this.dbClient.query('SELECT * FROM projects WHERE id = $1', [id]);
      if (result.rows.length > 0) {
        return result.rows[0];
      }
      return null;
    } catch (error) {
      console.error('Error fetching project:', error);
      throw new Error('Could not fetch project');
    }
  }

  async createProject(project: Omit<Project, 'id'>): Promise<Project> {
    try {
      const result = await this.dbClient.query(
        'INSERT INTO projects (name, description, start_date, end_date) VALUES ($1, $2, $3, $4) RETURNING *',
        [project.name, project.description, project.startDate, project.endDate]
      );
      return result.rows[0];
    } catch (error) {
      console.error('Error creating project:', error);
      throw new Error('Could not create project');
    }
  }

  async updateProject(id: number, project: Partial<Omit<Project, 'id'>>): Promise<Project | null> {
    try {
      const fields = Object.keys(project);
      const values = Object.values(project);
      const setClause = fields.map((field, index) => `${field} = $${index + 1}`).join(', ');
      const result = await this.dbClient.query(
        `UPDATE projects SET ${setClause} WHERE id = $${fields.length + 1} RETURNING *`,
        [...values, id]
      );
      if (result.rows.length > 0) {
        return result.rows[0];
      }
      return null;
    } catch (error) {
      console.error('Error updating project:', error);
      throw new Error('Could not update project');
    }
  }

  async deleteProject(id: number): Promise<boolean> {
    try {
      const result = await this.dbClient.query('DELETE FROM projects WHERE id = $1', [id]);
      return result.rowCount > 0;
    } catch (error) {
      console.error('Error deleting project:', error);
      throw new Error('Could not delete project');
    }
  }
}

export default ProjectService;

