import { Request, Response, NextFunction } from 'express';

// Validator for checking required fields in a request body
export const validateRequiredFields = (requiredFields: string[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const missingFields = requiredFields.filter(field => !req.body[field]);
    if (missingFields.length > 0) {
      return res.status(400).json({
        error: `Missing required fields: ${missingFields.join(', ')}`
      });
    }
    next();
  };
};

// Validator for checking if a field is a valid email
export const validateEmail = (field: string) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const email = req.body[field];
    const emailRegex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/;
    if (email && !emailRegex.test(email)) {
      return res.status(400).json({
        error: `Invalid email format for field: ${field}`
      });
    }
    next();
  };
};

// Validator for checking if a field is a valid date
export const validateDate = (field: string) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const date = req.body[field];
    if (date && isNaN(Date.parse(date))) {
      return res.status(400).json({
        error: `Invalid date format for field: ${field}`
      });
    }
    next();
  };
};

