  if (error) {
    return <div>Error: {error}</div>;
  }

  if (!release) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h2>Release {release.version}</h2>
      <p>Date: {release.date}</p>
      <h3>Features</h3>
      <ul>
        {release.features.map((feature, index) => (
          <li key={index}>{feature}</li>
        ))}
      </ul>
      <h3>Bugs Fixed</h3>
      <ul>
        {release.bugsFixed.map((bug, index) => (
          <li key={index}>{bug}</li>
        ))}
      </ul>
      <h3>Notes</h3>
      <p>{release.notes}</p>
    </div>
