import { Pool } from 'pg';

class SprintRepository {
  private pool: Pool;

  constructor(pool: Pool) {
    this.pool = pool;
  }

  async getAllSprints(projectId: number) {
    const query = 'SELECT * FROM sprints WHERE project_id = $1';
    const result = await this.pool.query(query, [projectId]);
    return result.rows;
  }

  async getSprintById(sprintId: number) {
    const query = 'SELECT * FROM sprints WHERE id = $1';
    const result = await this.pool.query(query, [sprintId]);
    return result.rows[0];
  }

  async createSprint(projectId: number, name: string, startDate: Date, endDate: Date) {
    const query = 'INSERT INTO sprints (project_id, name, start_date, end_date) VALUES ($1, $2, $3, $4) RETURNING *';
    const result = await this.pool.query(query, [projectId, name, startDate, endDate]);
    return result.rows[0];
  }

  async updateSprint(sprintId: number, name: string, startDate: Date, endDate: Date) {
    const query = 'UPDATE sprints SET name = $1, start_date = $2, end_date = $3 WHERE id = $4 RETURNING *';
    const result = await this.pool.query(query, [name, startDate, endDate, sprintId]);
    return result.rows[0];
  }

  async deleteSprint(sprintId: number) {
    const query = 'DELETE FROM sprints WHERE id = $1';
    await this.pool.query(query, [sprintId]);
  }
}

export default SprintRepository;

