import { FastifyReply, FastifyRequest } from 'fastify';

export const errorHandler = async (error: any, request: FastifyRequest, reply: FastifyReply) => {
  const statusCode = error.statusCode || 500;
  const errorMessage = error.message || 'Internal Server Error';

  reply.status(statusCode).send({
    error: {
      message: errorMessage,
      statusCode,
    },
  });
};

import { FastifyRequest, FastifyReply } from 'fastify';

export async function authMiddleware(request: FastifyRequest, reply: FastifyReply, done: Function) {
  try {
    const authHeader = request.headers['authorization'];
    if (!authHeader) {
      return reply.status(401).send({ error: 'Authorization header missing' });
    }

    const token = authHeader.split(' ')[1];
    if (!token) {
      return reply.status(401).send({ error: 'Token missing' });
    }

    // Here you would typically verify the token using a library like jsonwebtoken
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // request.user = decoded;

    done();
  } catch (error) {
    return reply.status(401).send({ error: 'Invalid token' });
  }
}

