  private sprints: Sprint[] = [mockSprintData];

  async findById(id: number): Promise<Sprint | null> {
    return this.sprints.find(sprint => sprint.id === id) || null;
  }

  async create(sprint: Sprint): Promise<Sprint> {
    this.sprints.push(sprint);
    return sprint;
  }

  async update(id: number, sprint: Partial<Sprint>): Promise<Sprint | null> {
    const index = this.sprints.findIndex(s => s.id === id);
    if (index !== -1) {
      this.sprints[index] = { ...this.sprints[index], ...sprint };
      return this.sprints[index];
    }
    return null;
  }

  async delete(id: number): Promise<boolean> {
    const index = this.sprints.findIndex(s => s.id === id);
    if (index !== -1) {
      this.sprints.splice(index, 1);
      return true;
    }
    return false;
  }
}

