import { renderHook, act } from '@testing-library/react-hooks';
import useAuth from '../../src/hooks/useAuth';
import { AuthProvider } from '../../src/context/AuthContext';

// Mocking the API call
jest.mock('../../src/api/auth', () => ({
  login: jest.fn(() => Promise.resolve({ token: 'fake-token' })),
  logout: jest.fn(() => Promise.resolve()),
}));

const mockUser = {
  username: 'testuser',
  password: 'password123',
};

describe('useAuth Hook', () => {
  it('should login a user and set the token', async () => {
    const { result } = renderHook(() => useAuth(), {
      wrapper: AuthProvider,
    });

    await act(async () => {
      await result.current.login(mockUser.username, mockUser.password);
    });

    expect(result.current.token).toBe('fake-token');
  });

  it('should logout a user and clear the token', async () => {
    const { result } = renderHook(() => useAuth(), {
      wrapper: AuthProvider,
    });

    await act(async () => {
      await result.current.login(mockUser.username, mockUser.password);
      await result.current.logout();
    });

    expect(result.current.token).toBe(null);
  });

  it('should handle login errors', async () => {
    jest.mock('../../src/api/auth', () => ({
      login: jest.fn(() => Promise.reject(new Error('Invalid credentials'))),
    }));

    const { result } = renderHook(() => useAuth(), {
      wrapper: AuthProvider,
    });

    await act(async () => {
      try {
        await result.current.login('wronguser', 'wrongpassword');
      } catch (error) {
        expect(error.message).toBe('Invalid credentials');
      }
    });

    expect(result.current.token).toBe(null);
  });
});

