import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { SprintService } from '../services/SprintService';

class SprintController {
  private sprintService: SprintService;

  constructor(sprintService: SprintService) {
    this.sprintService = sprintService;
  }

  async getSprints(request: FastifyRequest, reply: FastifyReply) {
    try {
      const sprints = await this.sprintService.getAllSprints();
      reply.send(sprints);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch sprints' });
    }
  }

  async getSprintById(request: FastifyRequest, reply: FastifyReply) {
    try {
      const { id } = request.params as { id: string };
      const sprint = await this.sprintService.getSprintById(id);
      if (sprint) {
        reply.send(sprint);
      } else {
        reply.status(404).send({ error: 'Sprint not found' });
      }
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch sprint' });
    }
  }

  async createSprint(request: FastifyRequest, reply: FastifyReply) {
    try {
      const sprintData = request.body;
      const newSprint = await this.sprintService.createSprint(sprintData);
      reply.status(201).send(newSprint);
    } catch (error) {
      reply.status(400).send({ error: 'Failed to create sprint' });
    }
  }

  async updateSprint(request: FastifyRequest, reply: FastifyReply) {
    try {
      const { id } = request.params as { id: string };
      const sprintData = request.body;
      const updatedSprint = await this.sprintService.updateSprint(id, sprintData);
      if (updatedSprint) {
        reply.send(updatedSprint);
      } else {
        reply.status(404).send({ error: 'Sprint not found' });
      }
    } catch (error) {
      reply.status(400).send({ error: 'Failed to update sprint' });
    }
  }

  async deleteSprint(request: FastifyRequest, reply: FastifyReply) {
    try {
      const { id } = request.params as { id: string };
      const success = await this.sprintService.deleteSprint(id);
      if (success) {
        reply.status(204).send();
      } else {
        reply.status(404).send({ error: 'Sprint not found' });
      }
    } catch (error) {
      reply.status(500).send({ error: 'Failed to delete sprint' });
    }
  }
}

export default function (fastify: FastifyInstance, opts: any, done: () => void) {
  const sprintService = new SprintService();
  const controller = new SprintController(sprintService);

  fastify.get('/sprints', controller.getSprints.bind(controller));
  fastify.get('/sprints/:id', controller.getSprintById.bind(controller));
  fastify.post('/sprints', controller.createSprint.bind(controller));
  fastify.put('/sprints/:id', controller.updateSprint.bind(controller));
  fastify.delete('/sprints/:id', controller.deleteSprint.bind(controller));

  done();
}

