import { FastifyInstance } from 'fastify';
import { ProjectRepository } from '../repositories/ProjectRepository';
import { Project } from '../models/Project';

export class ProjectService {
  private projectRepository: ProjectRepository;

  constructor(projectRepository: ProjectRepository) {
    this.projectRepository = projectRepository;
  }

  async createProject(data: Partial<Project>): Promise<Project> {
    try {
      if (!data.name || !data.startDate) {
        throw new Error('Project name and start date are required');
      }
      const newProject = await this.projectRepository.create(data);
      return newProject;
    } catch (error) {
      throw new Error(`Failed to create project: ${error.message}`);
    }
  }

  async getProjectById(projectId: string): Promise<Project | null> {
    try {
      if (!projectId) {
        throw new Error('Project ID is required');
      }
      const project = await this.projectRepository.findById(projectId);
      return project;
    } catch (error) {
      throw new Error(`Failed to retrieve project: ${error.message}`);
    }
  }

  async updateProject(projectId: string, data: Partial<Project>): Promise<Project | null> {
    try {
      if (!projectId) {
        throw new Error('Project ID is required');
      }
      const updatedProject = await this.projectRepository.update(projectId, data);
      return updatedProject;
    } catch (error) {
      throw new Error(`Failed to update project: ${error.message}`);
    }
  }

  async deleteProject(projectId: string): Promise<void> {
    try {
      if (!projectId) {
        throw new Error('Project ID is required');
      }
      await this.projectRepository.delete(projectId);
    } catch (error) {
      throw new Error(`Failed to delete project: ${error.message}`);
    }
  }

  async listProjects(): Promise<Project[]> {
    try {
      const projects = await this.projectRepository.findAll();
      return projects;
    } catch (error) {
      throw new Error(`Failed to list projects: ${error.message}`);
    }
  }
}

