import { Entity, PrimaryGeneratedColumn, Column, ManyToOne, OneToMany } from 'typeorm';
import { Projeto } from './Projeto';
import { HistoriaDeUsuario } from './HistoriaDeUsuario';

@Entity()
export class Sprint {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ type: 'varchar', length: 100, nullable: false })
  nome: string;

  @Column({ type: 'text', nullable: true })
  descricao: string;

  @Column({ type: 'date', nullable: false })
  dataInicio: Date;

  @Column({ type: 'date', nullable: false })
  dataFim: Date;

  @ManyToOne(() => Projeto, projeto => projeto.sprints, { nullable: false, onDelete: 'CASCADE' })
  projeto: Projeto;

  @OneToMany(() => HistoriaDeUsuario, historia => historia.sprint)
  historiasDeUsuario: HistoriaDeUsuario[];

  constructor(nome: string, dataInicio: Date, dataFim: Date, projeto: Projeto, descricao?: string) {
    if (!nome || !dataInicio || !dataFim || !projeto) {
      throw new Error('Nome, datas e projeto são obrigatórios para criar uma Sprint.');
    }
    this.nome = nome;
    this.dataInicio = dataInicio;
    this.dataFim = dataFim;
    this.projeto = projeto;
    this.descricao = descricao || '';
  }

  isValidDateRange(): boolean {
    return this.dataInicio < this.dataFim;
  }

  validate(): void {
    if (!this.isValidDateRange()) {
      throw new Error('A data de início deve ser anterior à data de fim.');
    }
  }
}

export interface Project {
  id: number;
  name: string;
  description: string;
  startDate: Date;
  endDate: Date;
  status: 'Not Started' | 'In Progress' | 'Completed';
  budget: number;
  clientName: string;
  teamMembers: string[];
  createdAt: Date;
  updatedAt: Date;
}

export class ProjectModel {
  private projects: Project[] = [];

  public createProject(project: Project): Project {
    try {
      if (!project.name || !project.startDate || !project.endDate) {
        throw new Error('Missing required fields');
      }
      project.id = this.projects.length + 1;
      project.createdAt = new Date();
      project.updatedAt = new Date();
      this.projects.push(project);
      return project;
    } catch (error) {
      console.error('Error creating project:', error);
      throw error;
    }
  }

  public getProjectById(id: number): Project | undefined {
    try {
      return this.projects.find(project => project.id === id);
    } catch (error) {
      console.error('Error retrieving project:', error);
      throw error;
    }
  }

  public updateProject(id: number, updatedProject: Partial<Project>): Project | undefined {
    try {
      const projectIndex = this.projects.findIndex(project => project.id === id);
      if (projectIndex === -1) {
        throw new Error('Project not found');
      }
      const project = this.projects[projectIndex];
      this.projects[projectIndex] = { ...project, ...updatedProject, updatedAt: new Date() };
      return this.projects[projectIndex];
    } catch (error) {
      console.error('Error updating project:', error);
      throw error;
    }
  }

  public deleteProject(id: number): boolean {
    try {
      const projectIndex = this.projects.findIndex(project => project.id === id);
      if (projectIndex === -1) {
        throw new Error('Project not found');
      }
      this.projects.splice(projectIndex, 1);
      return true;
    } catch (error) {
      console.error('Error deleting project:', error);
      throw error;
    }
  }
}

import { FastifyInstance } from 'fastify';
