interface UserStory {
  id: number;
  title: string;
  description: string;
  status: 'todo' | 'in-progress' | 'done';
  projectId: number;
}

class UserStoryService {
  private db: Pool;

  constructor(db: Pool) {
    this.db = db;
  }

  async createUserStory(userStory: Omit<UserStory, 'id'>): Promise<UserStory> {
    try {
      const { title, description, status, projectId } = userStory;
      if (!title || !description || !status || !projectId) {
        throw new Error('Missing required fields');
      }

      const result = await this.db.query(
        'INSERT INTO user_stories (title, description, status, project_id) VALUES ($1, $2, $3, $4) RETURNING *',
        [title, description, status, projectId]
      );

      return result.rows[0];
    } catch (error) {
      console.error('Error creating user story:', error);
      throw new Error('Could not create user story');
    }
  }

  async getUserStoriesByProject(projectId: number): Promise<UserStory[]> {
    try {
      if (!projectId) {
        throw new Error('Project ID is required');
      }

      const result = await this.db.query(
        'SELECT * FROM user_stories WHERE project_id = $1',
        [projectId]
      );

      return result.rows;
    } catch (error) {
      console.error('Error fetching user stories:', error);
      throw new Error('Could not fetch user stories');
    }
  }

  async updateUserStoryStatus(id: number, status: UserStory['status']): Promise<UserStory> {
    try {
      if (!id || !status) {
        throw new Error('ID and status are required');
      }

      const result = await this.db.query(
        'UPDATE user_stories SET status = $1 WHERE id = $2 RETURNING *',
        [status, id]
      );

      if (result.rows.length === 0) {
        throw new Error('User story not found');
      }

      return result.rows[0];
    } catch (error) {
      console.error('Error updating user story status:', error);
      throw new Error('Could not update user story status');
    }
  }
}

export default UserStoryService;

