    this.status = status;
    this.project = project;
    this.sprint = sprint || null;
  }
}

import { FastifyRequest, FastifyReply } from 'fastify';
import jwt from 'jsonwebtoken';

const secretKey = process.env.JWT_SECRET || 'defaultSecretKey';

export const authenticate = async (request: FastifyRequest, reply: FastifyReply) => {
  try {
    const authHeader = request.headers['authorization'];
    if (!authHeader) {
      return reply.status(401).send({ error: 'Authorization header missing' });
    }

    const token = authHeader.split(' ')[1];
    if (!token) {
      return reply.status(401).send({ error: 'Token missing' });
    }

    jwt.verify(token, secretKey, (err, user) => {
      if (err) {
        return reply.status(403).send({ error: 'Token is not valid' });
      }
      request.user = user;
    });
  } catch (error) {
    return reply.status(500).send({ error: 'Internal Server Error' });
  }
};

export const authorize = (roles: string[]) => {
  return (request: FastifyRequest, reply: FastifyReply, done: Function) => {
    if (!request.user || !roles.includes(request.user.role)) {
      return reply.status(403).send({ error: 'Forbidden' });
    }
    done();
  };
};

