import { FastifyInstance } from 'fastify';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcrypt';
import { UserRepository } from '../repositories/user.repository';

/**
 * Service responsible for handling authentication-related operations.
 */
export class AuthService {
  private userRepository: UserRepository;
  private jwtSecret: string;

  /**
   * Initializes the AuthService with necessary dependencies.
   * @param userRepository - Repository for accessing user data.
   * @param jwtSecret - Secret key for signing JWT tokens.
   */
  constructor(userRepository: UserRepository, jwtSecret: string) {
    this.userRepository = userRepository;
    this.jwtSecret = jwtSecret;
  }

  /**
   * Authenticates a user by their email and password.
   * @param email - The user's email.
   * @param password - The user's password.
   * @returns A promise that resolves to a JWT token if authentication is successful.
   */
  async authenticate(email: string, password: string): Promise<string> {
    const user = await this.userRepository.findByEmail(email);
    if (!user) {
      throw new Error('User not found');
    }

    const isPasswordValid = await bcrypt.compare(password, user.passwordHash);
    if (!isPasswordValid) {
      throw new Error('Invalid password');
    }

    return this.generateToken(user.id);
  }

  /**
   * Generates a JWT token for a given user ID.
   * @param userId - The ID of the user.
   * @returns A JWT token.
   */
  private generateToken(userId: string): string {
    return jwt.sign({ userId }, this.jwtSecret, { expiresIn: '1h' });
  }

  /**
   * Registers a new user with the given email and password.
   * @param email - The user's email.
   * @param password - The user's password.
   * @returns A promise that resolves to the newly created user ID.
   */
  async register(email: string, password: string): Promise<string> {
    const existingUser = await this.userRepository.findByEmail(email);
    if (existingUser) {
      throw new Error('Email already in use');
    }

    const passwordHash = await bcrypt.hash(password, 10);
    const userId = await this.userRepository.create({ email, passwordHash });
    return userId;
  }
}

/**
 * Registers authentication routes on the given Fastify instance.
 * @param app - The Fastify instance.
 * @param authService - The AuthService instance.
 */
export function registerAuthRoutes(app: FastifyInstance, authService: AuthService) {
  app.post('/auth/login', async (request, reply) => {
    try {
      const { email, password } = request.body as { email: string; password: string };
      const token = await authService.authenticate(email, password);
      reply.send({ token });
    } catch (error) {
      reply.status(401).send({ error: error.message });
    }
  });

  app.post('/auth/register', async (request, reply) => {
    try {
      const { email, password } = request.body as { email: string; password: string };
      const userId = await authService.register(email, password);
      reply.send({ userId });
    } catch (error) {
      reply.status(400).send({ error: error.message });
    }
  });
}

