import { Pool } from 'pg';

/**
 * Repository for managing project-related database operations.
 */
export class ProjectRepository {
  private pool: Pool;

  /**
   * Initializes the repository with a PostgreSQL connection pool.
   * @param pool - The PostgreSQL connection pool.
   */
  constructor(pool: Pool) {
    this.pool = pool;
  }

  /**
   * Retrieves a project by its ID.
   * @param projectId - The ID of the project to retrieve.
   * @returns A promise that resolves to the project data.
   */
  async getProjectById(projectId: string): Promise<any> {
    const query = 'SELECT * FROM projects WHERE id = $1';
    const result = await this.pool.query(query, [projectId]);
    return result.rows[0];
  }

  /**
   * Creates a new project in the database.
   * @param projectData - The data of the project to create.
   * @returns A promise that resolves to the created project ID.
   */
  async createProject(projectData: any): Promise<string> {
    const query = 'INSERT INTO projects (name, description, start_date, end_date) VALUES ($1, $2, $3, $4) RETURNING id';
    const values = [projectData.name, projectData.description, projectData.start_date, projectData.end_date];
    const result = await this.pool.query(query, values);
    return result.rows[0].id;
  }

  /**
   * Updates an existing project in the database.
   * @param projectId - The ID of the project to update.
   * @param projectData - The new data for the project.
   * @returns A promise that resolves when the update is complete.
   */
  async updateProject(projectId: string, projectData: any): Promise<void> {
    const query = 'UPDATE projects SET name = $1, description = $2, start_date = $3, end_date = $4 WHERE id = $5';
    const values = [projectData.name, projectData.description, projectData.start_date, projectData.end_date, projectId];
    await this.pool.query(query, values);
  }

  /**
   * Deletes a project from the database.
   * @param projectId - The ID of the project to delete.
   * @returns A promise that resolves when the deletion is complete.
   */
  async deleteProject(projectId: string): Promise<void> {
    const query = 'DELETE FROM projects WHERE id = $1';
    await this.pool.query(query, [projectId]);
  }
}

