import { Pool } from 'pg';

/**
 * SprintRepository is responsible for handling database operations related to Sprints.
 */
export class SprintRepository {
  private pool: Pool;

  /**
   * Initializes a new instance of the SprintRepository class.
   * @param pool - The PostgreSQL connection pool.
   */
  constructor(pool: Pool) {
    this.pool = pool;
  }

  /**
   * Retrieves all sprints from the database.
   * @returns A promise that resolves to an array of sprints.
   */
  async getAllSprints(): Promise<any[]> {
    const client = await this.pool.connect();
    try {
      const result = await client.query('SELECT * FROM sprints');
      return result.rows;
    } finally {
      client.release();
    }
  }

  /**
   * Retrieves a sprint by its ID.
   * @param id - The ID of the sprint to retrieve.
   * @returns A promise that resolves to the sprint, or null if not found.
   */
  async getSprintById(id: number): Promise<any | null> {
    const client = await this.pool.connect();
    try {
      const result = await client.query('SELECT * FROM sprints WHERE id = $1', [id]);
      return result.rows[0] || null;
    } finally {
      client.release();
    }
  }

  /**
   * Creates a new sprint in the database.
   * @param sprint - The sprint data to insert.
   * @returns A promise that resolves to the created sprint.
   */
  async createSprint(sprint: any): Promise<any> {
    const client = await this.pool.connect();
    try {
      const result = await client.query(
        'INSERT INTO sprints (name, start_date, end_date) VALUES ($1, $2, $3) RETURNING *',
        [sprint.name, sprint.start_date, sprint.end_date]
      );
      return result.rows[0];
    } finally {
      client.release();
    }
  }

  /**
   * Updates an existing sprint in the database.
   * @param id - The ID of the sprint to update.
   * @param sprint - The sprint data to update.
   * @returns A promise that resolves to the updated sprint, or null if not found.
   */
  async updateSprint(id: number, sprint: any): Promise<any | null> {
    const client = await this.pool.connect();
    try {
      const result = await client.query(
        'UPDATE sprints SET name = $1, start_date = $2, end_date = $3 WHERE id = $4 RETURNING *',
        [sprint.name, sprint.start_date, sprint.end_date, id]
      );
      return result.rows[0] || null;
    } finally {
      client.release();
    }
  }

  /**
   * Deletes a sprint from the database.
   * @param id - The ID of the sprint to delete.
   * @returns A promise that resolves to true if the sprint was deleted, or false if not found.
   */
  async deleteSprint(id: number): Promise<boolean> {
    const client = await this.pool.connect();
    try {
      const result = await client.query('DELETE FROM sprints WHERE id = $1', [id]);
      return result.rowCount > 0;
    } finally {
      client.release();
    }
  }
}

