   * @param reply - The Fastify reply object.
   */
  private async updateSprint(request: FastifyRequest, reply: FastifyReply): Promise<void> {
    try {
      const sprintId = request.params.id;
      const sprintData: Sprint = request.body;
      const updatedSprint = await this.sprintService.updateSprint(sprintId, sprintData);
      if (updatedSprint) {
        reply.send(updatedSprint);
      } else {
        reply.status(404).send({ error: 'Sprint not found' });
      }
    } catch (error) {
      reply.status(400).send({ error: 'Failed to update sprint' });
    }
  }

  /**
   * Handler to delete a sprint.
   * @param request - The Fastify request object.
   * @param reply - The Fastify reply object.
   */
  private async deleteSprint(request: FastifyRequest, reply: FastifyReply): Promise<void> {
    try {
      const sprintId = request.params.id;
      const success = await this.sprintService.deleteSprint(sprintId);
      if (success) {
        reply.status(204).send();
      } else {
        reply.status(404).send({ error: 'Sprint not found' });
      }
    } catch (error) {
      reply.status(500).send({ error: 'Failed to delete sprint' });
    }
  }
}

