/**
 * Registers the sprint service routes with the Fastify instance.
 * @param fastify - The Fastify instance.
 */
export const registerSprintRoutes = (fastify: FastifyInstance) => {
  const sprintService = new SprintService(new SprintRepository());

  fastify.get('/sprints', async (request, reply) => {
    const sprints = await sprintService.getAllSprints();
    reply.send(sprints);
  });

  fastify.get('/sprints/:id', async (request, reply) => {
    const { id } = request.params as { id: string };
    const sprint = await sprintService.getSprintById(id);
    if (sprint) {
      reply.send(sprint);
    } else {
      reply.status(404).send({ error: 'Sprint not found' });
    }
  });

  fastify.post('/sprints', async (request, reply) => {
    const sprintData = request.body as Partial<Sprint>;
    const newSprint = await sprintService.createSprint(sprintData);
    reply.status(201).send(newSprint);
  });

  fastify.put('/sprints/:id', async (request, reply) => {
    const { id } = request.params as { id: string };
    const sprintData = request.body as Partial<Sprint>;
    const updatedSprint = await sprintService.updateSprint(id, sprintData);
    if (updatedSprint) {
      reply.send(updatedSprint);
    } else {
      reply.status(404).send({ error: 'Sprint not found' });
    }
  });

  fastify.delete('/sprints/:id', async (request, reply) => {
    const { id } = request.params as { id: string };
    const success = await sprintService.deleteSprint(id);
    if (success) {
      reply.status(204).send();
    } else {
      reply.status(404).send({ error: 'Sprint not found' });
    }
  });
};

