import { z } from 'zod';
import { UserRepository } from '../repositories/user.repository';
import { KafkaProducer } from '../kafka/producer';

/**
 * @class UserService
 * @description Provides methods to manage users.
 */
export class UserService {
  private userRepository: UserRepository;
  private kafkaProducer: KafkaProducer;

  constructor(userRepository: UserRepository, kafkaProducer: KafkaProducer) {
    this.userRepository = userRepository;
    this.kafkaProducer = kafkaProducer;
  }

  /**
   * @method createUser
   * @description Creates a new user and publishes an event to Kafka.
   * @param {object} userData - The data of the user to be created.
   * @returns {Promise<object>} The created user.
   */
  async createUser(userData: object): Promise<object> {
    const userSchema = z.object({
      name: z.string().min(1),
      email: z.string().email(),
      password: z.string().min(6)
    });

    try {
      const validatedData = userSchema.parse(userData);
      const user = await this.userRepository.create(validatedData);
      await this.kafkaProducer.send('user.created', user);
      return user;
    } catch (error) {
      console.error('Error creating user:', error);
      throw new Error('Failed to create user');
    }
  }

  /**
   * @method getUserById
   * @description Retrieves a user by their ID.
   * @param {string} userId - The ID of the user to retrieve.
   * @returns {Promise<object | null>} The user if found, otherwise null.
   */
  async getUserById(userId: string): Promise<object | null> {
    try {
      const user = await this.userRepository.findById(userId);
      return user;
    } catch (error) {
      console.error('Error retrieving user:', error);
      throw new Error('Failed to retrieve user');
    }
  }
}

