import { FastifyRequest, FastifyReply } from 'fastify';
import { verifyToken } from '../services/auth.service';
import { z } from 'zod';

/**
 * Middleware to authenticate requests using JWT.
 * @param request - Fastify request object.
 * @param reply - Fastify reply object.
 * @param done - Callback to signal completion.
 */
export async function authMiddleware(request: FastifyRequest, reply: FastifyReply, done: Function) {
  try {
    const authHeader = request.headers['authorization'];
    if (!authHeader) {
      reply.status(401).send({ error: 'Authorization header missing' });
      return;
    }

    const token = authHeader.split(' ')[1];
    if (!token) {
      reply.status(401).send({ error: 'Token missing' });
      return;
    }

    const tokenSchema = z.string().min(1, 'Token cannot be empty');
    tokenSchema.parse(token);

    const user = await verifyToken(token);
    if (!user) {
      reply.status(401).send({ error: 'Invalid token' });
      return;
    }

    request.user = user;
    done();
  } catch (error) {
    reply.status(500).send({ error: 'Internal Server Error' });
  }
}

