/**
 * Configuration schema for Redis connection.
 */
const redisConfigSchema = z.object({
  host: z.string().nonempty(),
  port: z.number().int().positive(),
  password: z.string().optional(),
  db: z.number().int().nonnegative().optional(),
});

/**
 * Initializes and configures a Redis client.
 * @param {FastifyInstance} fastify - The Fastify instance.
 * @param {object} options - The configuration options for Redis.
 * @returns {Redis.Redis} The configured Redis client.
 */
export function createRedisClient(fastify: FastifyInstance, options: object): Redis.Redis {
  const config = redisConfigSchema.parse(options);

  const redis = new Redis({
    host: config.host,
    port: config.port,
    password: config.password,
    db: config.db,
  });

  redis.on('error', (err) => {
    fastify.log.error(`Redis error: ${err}`);
  });

  redis.on('connect', () => {
    fastify.log.info('Connected to Redis');
  });

  return redis;
}

