import { FastifyInstance } from 'fastify';
import { createLogger, transports, format } from 'winston';
import { OpenTelemetry } from '@opentelemetry/api';
import { z } from 'zod';

/**
 * @class LoggingService
 * @description Provides logging capabilities using Winston and integrates with OpenTelemetry for tracing.
 */
class LoggingService {
  private logger;

  constructor() {
    this.logger = createLogger({
      level: 'info',
      format: format.combine(
        format.timestamp(),
        format.json()
      ),
      transports: [
        new transports.Console(),
        new transports.File({ filename: 'logs/error.log', level: 'error' }),
        new transports.File({ filename: 'logs/combined.log' })
      ]
    });
  }

  /**
   * Logs an informational message.
   * @param {string} message - The message to log.
   * @param {object} [meta] - Additional metadata to log.
   */
  logInfo(message: string, meta?: object) {
    this.logger.info(message, meta);
  }

  /**
   * Logs an error message.
   * @param {string} message - The message to log.
   * @param {object} [meta] - Additional metadata to log.
   */
  logError(message: string, meta?: object) {
    this.logger.error(message, meta);
  }

  /**
   * Integrates logging with OpenTelemetry for distributed tracing.
   * @param {FastifyInstance} app - The Fastify application instance.
   */
  integrateWithOpenTelemetry(app: FastifyInstance) {
    const tracer = OpenTelemetry.getTracer('default');
    app.addHook('onRequest', async (request, reply) => {
      const span = tracer.startSpan('http_request', {
        attributes: { method: request.method, url: request.url }
      });
      request.raw.span = span;
    });

    app.addHook('onResponse', async (request, reply) => {
      const span = request.raw.span;
      if (span) {
        span.end();
      }
    });
  }
}

export default LoggingService;

import { FastifyInstance } from 'fastify';
import { trace, context, propagation } from '@opentelemetry/api';
import { NodeTracerProvider } from '@opentelemetry/node';
import { SimpleSpanProcessor } from '@opentelemetry/tracing';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';

/**
 * Initializes OpenTelemetry tracing for the Fastify application.
 * @param {FastifyInstance} app - The Fastify application instance.
 */
export function setupTracing(app: FastifyInstance): void {
  const provider = new NodeTracerProvider();

  // Configure the Jaeger exporter
  const exporter = new JaegerExporter({
    serviceName: 'my-fastify-service',
    endpoint: process.env.JAEGER_ENDPOINT || 'http://localhost:14268/api/traces',
  });

  provider.addSpanProcessor(new SimpleSpanProcessor(exporter));
  provider.register();

  // Add a hook to start a new span for each request
  app.addHook('onRequest', async (request, reply) => {
    const span = trace.getTracer('default').startSpan('http_request', {
      attributes: {
        'http.method': request.method,
        'http.url': request.url,
      },
    });

    // Set the span context for the request
    context.with(trace.setSpan(context.active(), span), () => {
      propagation.inject(context.active(), request.headers);
    });

    reply.raw.on('finish', () => {
      span.setAttribute('http.status_code', reply.statusCode);
      span.end();
    });
  });
}

