import { test } from 'tap';
import { buildApp } from '../../app';
import { createUser, deleteUser } from '../../services/userService';

/**
 * E2E Test Suite for User Management
 *
 * This suite tests the end-to-end functionality of user management,
 * including user creation, retrieval, update, and deletion.
 */
test('User Management E2E Tests', async (t) => {
  const app = await buildApp();

  t.teardown(() => app.close());

  t.test('Create User', async (t) => {
    const userData = { name: 'John Doe', email: 'john.doe@example.com' };
    const response = await app.inject({
      method: 'POST',
      url: '/users',
      payload: userData,
    });

    t.equal(response.statusCode, 201, 'User should be created successfully');
    const user = response.json();
    t.match(user, { id: String, name: 'John Doe', email: 'john.doe@example.com' }, 'Response should match user data');
  });

  t.test('Get User', async (t) => {
    const user = await createUser({ name: 'Jane Doe', email: 'jane.doe@example.com' });
    const response = await app.inject({
      method: 'GET',
      url: `/users/${user.id}`,
    });

    t.equal(response.statusCode, 200, 'User should be retrieved successfully');
    t.match(response.json(), { id: user.id, name: 'Jane Doe', email: 'jane.doe@example.com' }, 'Response should match user data');
  });

  t.test('Update User', async (t) => {
    const user = await createUser({ name: 'Jake Doe', email: 'jake.doe@example.com' });
    const updatedData = { name: 'Jake Smith' };
    const response = await app.inject({
      method: 'PUT',
      url: `/users/${user.id}`,
      payload: updatedData,
    });

    t.equal(response.statusCode, 200, 'User should be updated successfully');
    t.match(response.json(), { id: user.id, name: 'Jake Smith', email: 'jake.doe@example.com' }, 'Response should reflect updated user data');
  });

  t.test('Delete User', async (t) => {
    const user = await createUser({ name: 'Jim Doe', email: 'jim.doe@example.com' });
    const response = await app.inject({
      method: 'DELETE',
      url: `/users/${user.id}`,
    });

    t.equal(response.statusCode, 204, 'User should be deleted successfully');

    const getResponse = await app.inject({
      method: 'GET',
      url: `/users/${user.id}`,
    });

    t.equal(getResponse.statusCode, 404, 'Deleted user should not be found');
  });
});

import { FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { generateReport } from '../services/report.service';

/**
 * Controller for handling report generation requests.
 */
export class ReportController {
  /**
   * Handles the request to generate a report.
   * @param request - Fastify request object.
   * @param reply - Fastify reply object.
   */
  async generateReportHandler(request: FastifyRequest, reply: FastifyReply) {
    const reportSchema = z.object({
      startDate: z.string().refine((date) => !isNaN(Date.parse(date)), {
        message: 'Invalid start date',
      }),
      endDate: z.string().refine((date) => !isNaN(Date.parse(date)), {
        message: 'Invalid end date',
      }),
      type: z.enum(['summary', 'detailed']),
    });

    try {
      const { startDate, endDate, type } = reportSchema.parse(request.body);
      const reportData = await generateReport(startDate, endDate, type);
      reply.send({ success: true, data: reportData });
    } catch (error) {
      reply.status(400).send({ success: false, error: error.message });
    }
  }
}

