import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { UserRepository } from '../repositories/user.repository';

/**
 * Service responsible for handling authentication logic.
 */
export class AuthService {
  private userRepository: UserRepository;

  constructor(userRepository: UserRepository) {
    this.userRepository = userRepository;
  }

  /**
   * Validates user credentials and returns a JWT token if successful.
   * @param email - User's email.
   * @param password - User's password.
   * @returns A promise that resolves to a JWT token.
   */
  async login(email: string, password: string): Promise<string> {
    const schema = z.object({
      email: z.string().email(),
      password: z.string().min(6)
    });

    try {
      schema.parse({ email, password });

      const user = await this.userRepository.findByEmail(email);
      if (!user) {
        throw new Error('Invalid email or password');
      }

      const isPasswordValid = await bcrypt.compare(password, user.passwordHash);
      if (!isPasswordValid) {
        throw new Error('Invalid email or password');
      }

      const token = jwt.sign({ userId: user.id }, process.env.JWT_SECRET!, {
        expiresIn: '1h'
      });

      return token;
    } catch (error) {
      throw new Error(`Authentication failed: ${error.message}`);
    }
  }

  /**
   * Registers a new user and returns a JWT token.
   * @param email - User's email.
   * @param password - User's password.
   * @returns A promise that resolves to a JWT token.
   */
  async register(email: string, password: string): Promise<string> {
    const schema = z.object({
      email: z.string().email(),
      password: z.string().min(6)
    });

    try {
      schema.parse({ email, password });

      const existingUser = await this.userRepository.findByEmail(email);
      if (existingUser) {
        throw new Error('Email already in use');
      }

      const passwordHash = await bcrypt.hash(password, 10);
      const newUser = await this.userRepository.create({ email, passwordHash });

      const token = jwt.sign({ userId: newUser.id }, process.env.JWT_SECRET!, {
        expiresIn: '1h'
      });

      return token;
    } catch (error) {
      throw new Error(`Registration failed: ${error.message}`);
    }
  }
}

/**
 * Registers authentication routes.
 * @param fastify - Fastify instance.
 */
export async function authRoutes(fastify: FastifyInstance) {
  const authService = new AuthService(new UserRepository());

  fastify.post('/api/v1/login', async (request, reply) => {
    const { email, password } = request.body as { email: string; password: string };
    try {
      const token = await authService.login(email, password);
      reply.send({ token });
    } catch (error) {
      reply.status(401).send({ error: error.message });
    }
  });

  fastify.post('/api/v1/register', async (request, reply) => {
    const { email, password } = request.body as { email: string; password: string };
    try {
      const token = await authService.register(email, password);
      reply.send({ token });
    } catch (error) {
      reply.status(400).send({ error: error.message });
    }
  });
