import { z } from 'zod';

/**
 * User model schema using Zod for validation.
 */
export const UserSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1, 'Name is required'),
  email: z.string().email('Invalid email format'),
  password: z.string().min(8, 'Password must be at least 8 characters long'),
  createdAt: z.date(),
  updatedAt: z.date(),
});

/**
 * TypeScript type for User based on the UserSchema.
 */
export type User = z.infer<typeof UserSchema>;

/**
 * Class representing a User entity.
 */
export class UserModel {
  private data: User;

  /**
   * Create a new UserModel instance.
   * @param userData - The user data to initialize the model.
   */
  constructor(userData: User) {
    this.data = userData;
  }

  /**
   * Get the user's name.
   * @returns The name of the user.
   */
  getName(): string {
    return this.data.name;
  }

  /**
   * Set a new name for the user.
   * @param name - The new name to set.
   */
  setName(name: string): void {
    if (name.length < 1) {
      throw new Error('Name cannot be empty');
    }
    this.data.name = name;
  }

  /**
   * Get the user's email.
   * @returns The email of the user.
   */
  getEmail(): string {
    return this.data.email;
  }

  /**
   * Set a new email for the user.
   * @param email - The new email to set.
   */
  setEmail(email: string): void {
    if (!z.string().email().safeParse(email).success) {
      throw new Error('Invalid email format');
    }
    this.data.email = email;
  }

  /**
   * Validate the user data against the schema.
   * @returns True if valid, throws an error otherwise.
   */
  validate(): boolean {
    const result = UserSchema.safeParse(this.data);
    if (!result.success) {
      throw new Error('User data validation failed');
    }
    return true;
  }
}

import { FastifyReply } from 'fastify';
import { ZodError } from 'zod';

/**
 * Handles errors in the application by sending appropriate responses.
 * @param {Error} error - The error object caught in the application.
 * @param {FastifyReply} reply - The Fastify reply object to send responses.
 */
export function errorHandler(error: Error, reply: FastifyReply): void {
  if (error instanceof ZodError) {
    reply.status(400).send({
      statusCode: 400,
      error: 'Bad Request',
      message: error.errors.map(e => e.message).join(', ')
    });
  } else {
    reply.status(500).send({
      statusCode: 500,
      error: 'Internal Server Error',
      message: 'An unexpected error occurred.'
    });
  }
}

import { createLogger, transports, format } from 'winston';

/**
 * Logger utility using Winston for structured logging.
 * Provides different logging levels and formats for development and production environments.
 */
export class Logger {
  private logger;

  constructor() {
    this.logger = createLogger({
      level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
      format: format.combine(
        format.timestamp(),
        format.printf(({ timestamp, level, message }) => {
          return `${timestamp} [${level.toUpperCase()}]: ${message}`;
        })
      ),
      transports: [
        new transports.Console(),
        new transports.File({ filename: 'application.log' })
      ]
    });
  }

  /**
   * Logs an info message.
   * @param message - The message to log.
   */
  public info(message: string): void {
    this.logger.info(message);
  }

  /**
   * Logs a debug message.
   * @param message - The message to log.
   */
  public debug(message: string): void {
    this.logger.debug(message);
  }

  /**
   * Logs an error message.
   * @param message - The message to log.
   */
  public error(message: string): void {
    this.logger.error(message);
  }
}

