import { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { authenticateUser, registerUser } from '../services/auth.service';

/**
 * Registers authentication routes.
 * @param app - The Fastify instance.
 */
export async function authRoutes(app: FastifyInstance) {
  /**
   * Schema for user registration.
   */
  const registerSchema = z.object({
    body: z.object({
      username: z.string().min(3),
      password: z.string().min(6),
      email: z.string().email(),
    }),
  });

  /**
   * Schema for user login.
   */
  const loginSchema = z.object({
    body: z.object({
      username: z.string(),
      password: z.string(),
    }),
  });

  /**
   * Route for user registration.
   */
  app.post('/api/v1/auth/register', { schema: registerSchema }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { username, password, email } = request.body as any;
      const user = await registerUser({ username, password, email });
      reply.code(201).send(user);
    } catch (error) {
      reply.code(400).send({ error: error.message });
    }
  });

  /**
   * Route for user login.
   */
  app.post('/api/v1/auth/login', { schema: loginSchema }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { username, password } = request.body as any;
      const token = await authenticateUser({ username, password });
      reply.code(200).send({ token });
    } catch (error) {
      reply.code(401).send({ error: error.message });
    }
  });
}

