import { Pool } from 'pg';
import { z } from 'zod';

/**
 * Database configuration and connection pool setup.
 * This module exports a configured PostgreSQL connection pool.
 */

// Define a schema for environment variables validation
const envSchema = z.object({
  DB_HOST: z.string().nonempty(),
  DB_PORT: z.string().transform(Number),
  DB_USER: z.string().nonempty(),
  DB_PASSWORD: z.string().nonempty(),
  DB_NAME: z.string().nonempty(),
});

// Validate and parse environment variables
const env = envSchema.parse(process.env);

// Create a new PostgreSQL connection pool
const pool = new Pool({
  host: env.DB_HOST,
  port: env.DB_PORT,
  user: env.DB_USER,
  password: env.DB_PASSWORD,
  database: env.DB_NAME,
  max: 10, // Maximum number of clients in the pool
  idleTimeoutMillis: 30000, // Close idle clients after 30 seconds
  connectionTimeoutMillis: 2000, // Return an error after 2 seconds if connection could not be established
});

/**
 * Get a client from the pool and execute a query.
 * @param {string} text - The SQL query text.
 * @param {Array} params - The parameters for the SQL query.
 * @returns {Promise} - A promise that resolves to the query result.
 */
export const query = (text, params) => {
  return pool.query(text, params);
};

/**
 * Close the database pool.
 * This should be called when the application is shutting down.
 */
export const closePool = async () => {
  await pool.end();
};

export default pool;

import Fastify from 'fastify';
import cors from '@fastify/cors';
import { ZodError } from 'zod';

/**
 * Initializes and configures the Fastify server.
 * @returns {FastifyInstance} Configured Fastify server instance.
 */
export function createServer() {
  const server = Fastify({
    logger: true,
  });

  // Enable CORS for all routes
  server.register(cors, {
    origin: '*',
  });

  // Global error handler
  server.setErrorHandler((error, request, reply) => {
    if (error instanceof ZodError) {
      reply.status(400).send({
        error: 'Validation Error',
        details: error.errors,
      });
    } else {
      server.log.error(error);
      reply.status(500).send({
        error: 'Internal Server Error',
      });
    }
  });

  // Health check endpoint
  server.get('/healthz', async (request, reply) => {
    return { status: 'ok' };
  });

  return server;
}

/**
 * Starts the Fastify server on the specified port.
 * @param {number} port - The port number to listen on.
 */
export async function startServer(port: number) {
  const server = createServer();
  try {
    await server.listen({ port });
    server.log.info(`Server listening on port ${port}`);
  } catch (err) {
    server.log.error(err);
    process.exit(1);
  }
}

