import { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { getProjects, createProject, updateProject, deleteProject } from '../../../services/projectService';

/**
 * Schema de validação para criação de projeto
 */
const createProjectSchema = z.object({
  name: z.string().min(1, 'O nome do projeto é obrigatório'),
  description: z.string().optional(),
  startDate: z.string().optional(),
  endDate: z.string().optional(),
});

/**
 * Schema de validação para atualização de projeto
 */
const updateProjectSchema = z.object({
  id: z.string().uuid('ID do projeto inválido'),
  name: z.string().min(1, 'O nome do projeto é obrigatório').optional(),
  description: z.string().optional(),
  startDate: z.string().optional(),
  endDate: z.string().optional(),
});

/**
 * Registra as rotas de projetos no Fastify
 * @param {FastifyInstance} app - Instância do Fastify
 */
export async function projectRoutes(app: FastifyInstance) {
  app.get('/api/v1/projects', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const projects = await getProjects();
      reply.send(projects);
    } catch (error) {
      reply.status(500).send({ error: 'Erro ao buscar projetos' });
    }
  });

  app.post('/api/v1/projects', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const projectData = createProjectSchema.parse(request.body);
      const newProject = await createProject(projectData);
      reply.status(201).send(newProject);
    } catch (error) {
      if (error instanceof z.ZodError) {
        reply.status(400).send({ error: error.errors });
      } else {
        reply.status(500).send({ error: 'Erro ao criar projeto' });
      }
    }
  });

  app.put('/api/v1/projects/:id', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const projectData = updateProjectSchema.parse({ ...request.body, id: request.params.id });
      const updatedProject = await updateProject(projectData);
      reply.send(updatedProject);
    } catch (error) {
      if (error instanceof z.ZodError) {
        reply.status(400).send({ error: error.errors });
      } else {
        reply.status(500).send({ error: 'Erro ao atualizar projeto' });
      }
    }
  });

  app.delete('/api/v1/projects/:id', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { id } = request.params;
      await deleteProject(id);
      reply.status(204).send();
    } catch (error) {
      reply.status(500).send({ error: 'Erro ao deletar projeto' });
    }
  });
}

