/**
 * @module ProjectModel
 *
 * Este módulo define o modelo de dados para um Projeto no sistema de gestão de projetos.
 *
 * Um Projeto é uma entidade central que agrupa tarefas, equipes e usuários, permitindo
 * o acompanhamento e gerenciamento de atividades dentro de um contexto específico.
 */

import { z } from 'zod';

/**
 * Esquema de validação para um Projeto usando Zod.
 *
 * - `id`: Identificador único do projeto.
 * - `name`: Nome do projeto, obrigatório e deve ter entre 3 e 100 caracteres.
 * - `description`: Descrição opcional do projeto, com no máximo 500 caracteres.
 * - `startDate`: Data de início do projeto, obrigatória.
 * - `endDate`: Data de término do projeto, opcional, mas deve ser posterior à data de início.
 * - `status`: Status atual do projeto, deve ser um dos valores predefinidos.
 */
export const ProjectSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(3).max(100),
  description: z.string().max(500).optional(),
  startDate: z.date(),
  endDate: z.date().optional().refine((date, ctx) => {
    if (date && ctx.parent.startDate && date <= ctx.parent.startDate) {
      return false;
    }
    return true;
  }, {
    message: 'A data de término deve ser posterior à data de início.'
  }),
  status: z.enum(['not_started', 'in_progress', 'completed', 'on_hold']),
});

/**
 * Interface que representa um Projeto.
 */
export type Project = z.infer<typeof ProjectSchema>;

