 *
 * @typedef {Object} Task
 * @property {string} id - Identificador único da tarefa.
 * @property {string} title - Título descritivo da tarefa.
 * @property {string} description - Descrição detalhada da tarefa.
 * @property {string} status - Status atual da tarefa (e.g., 'pendente', 'em progresso', 'concluída').
 * @property {string} assigneeId - ID do usuário responsável pela tarefa.
 * @property {Date} createdAt - Data de criação da tarefa.
 * @property {Date} updatedAt - Data da última atualização da tarefa.
 */

// Schema de validação para a entidade Task usando Zod
export const TaskSchema = z.object({
  id: z.string().uuid(),
  title: z.string().min(1, 'O título é obrigatório').max(100, 'O título deve ter no máximo 100 caracteres'),
  description: z.string().max(500, 'A descrição deve ter no máximo 500 caracteres').optional(),
  status: z.enum(['pendente', 'em progresso', 'concluída']),
  assigneeId: z.string().uuid().optional(),
  createdAt: z.date(),
  updatedAt: z.date(),
});

/**
 * Classe que representa uma Tarefa.
 */
export class Task {
  /**
   * Cria uma nova instância de Task.
   * @param {string} id - Identificador único da tarefa.
   * @param {string} title - Título descritivo da tarefa.
   * @param {string} description - Descrição detalhada da tarefa.
   * @param {string} status - Status atual da tarefa.
   * @param {string} assigneeId - ID do usuário responsável pela tarefa.
   * @param {Date} createdAt - Data de criação da tarefa.
   * @param {Date} updatedAt - Data da última atualização da tarefa.
   */
  constructor(id, title, description, status, assigneeId, createdAt, updatedAt) {
    this.id = id;
    this.title = title;
    this.description = description;
    this.status = status;
    this.assigneeId = assigneeId;
    this.createdAt = createdAt;
    this.updatedAt = updatedAt;
  }

  /**
   * Valida a tarefa atual usando o schema definido.
   * @returns {boolean} Retorna verdadeiro se a tarefa for válida.
   * @throws {Error} Lança um erro se a validação falhar.
   */
  validate() {
    const result = TaskSchema.safeParse(this);
    if (!result.success) {
      throw new Error('Validação da tarefa falhou: ' + result.error.errors.map(e => e.message).join(', '));
    }
    return true;
  }
}

