/**
 * Serviço de Notificação
 *
 * Este serviço é responsável por gerenciar o envio de notificações para os usuários.
 * As notificações podem ser enviadas por diferentes canais, como email ou push notifications.
 */
class NotificationService {
  private fastify: FastifyInstance;

  constructor(fastify: FastifyInstance) {
    this.fastify = fastify;
  }

  /**
   * Envia uma notificação para um usuário específico.
   *
   * @param userId - ID do usuário que receberá a notificação.
   * @param message - Mensagem a ser enviada na notificação.
   * @returns Promise<void>
   */
  async sendNotification(userId: string, message: string): Promise<void> {
    const notificationSchema = z.object({
      userId: z.string().uuid(),
      message: z.string().min(1),
    });

    try {
      notificationSchema.parse({ userId, message });
      // Lógica para envio de notificação
      this.fastify.log.info(`Notificação enviada para o usuário ${userId}: ${message}`);
    } catch (error) {
      this.fastify.log.error('Erro ao enviar notificação:', error);
      throw new Error('Falha ao enviar notificação.');
    }
  }
}

