interface ProjectDetailProps {
  projectId: string;
}

const ProjectDetail: React.FC<ProjectDetailProps> = ({ projectId }) => {
  // Estado para armazenar detalhes do projeto
  const [projectDetails, setProjectDetails] = React.useState(null);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);

  // Efeito para buscar detalhes do projeto ao montar o componente
  React.useEffect(() => {
    const fetchProjectDetails = async () => {
      try {
        const response = await fetch(`/api/v1/projects/${projectId}`);
        if (!response.ok) {
          throw new Error('Erro ao buscar detalhes do projeto');
        }
        const data = await response.json();
        setProjectDetails(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchProjectDetails();
  }, [projectId]);

  if (loading) return <p>Carregando...</p>;
  if (error) return <p>Erro: {error}</p>;

  return (
    <div>
      <h1>Detalhes do Projeto</h1>
      {projectDetails ? (
        <div>
          <h2>{projectDetails.name}</h2>
          <p>{projectDetails.description}</p>
          {/* Outros detalhes do projeto */}
        </div>
      ) : (
        <p>Projeto não encontrado.</p>
      )}
    </div>
  );
};

