import axios from 'axios';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:3000/api/v1',
  headers: {
    'Content-Type': 'application/json',
  },
});

/**
 * Função para realizar uma requisição GET na API.
 * @param endpoint - O endpoint da API a ser acessado.
 * @param params - Parâmetros de consulta opcionais.
 * @returns Uma Promise com os dados da resposta ou um erro.
 */
export const get = async (endpoint: string, params?: Record<string, any>) => {
  try {
    const response = await api.get(endpoint, { params });
    return response.data;
  } catch (error) {
    console.error('Erro ao realizar requisição GET:', error);
    throw error;
  }
};

/**
 * Função para realizar uma requisição POST na API.
 * @param endpoint - O endpoint da API a ser acessado.
 * @param data - Os dados a serem enviados no corpo da requisição.
 * @returns Uma Promise com os dados da resposta ou um erro.
 */
export const post = async (endpoint: string, data: Record<string, any>) => {
  try {
    const response = await api.post(endpoint, data);
    return response.data;
  } catch (error) {
    console.error('Erro ao realizar requisição POST:', error);
    throw error;
  }
};

/**
 * Função para realizar uma requisição PUT na API.
 * @param endpoint - O endpoint da API a ser acessado.
 * @param data - Os dados a serem enviados no corpo da requisição.
 * @returns Uma Promise com os dados da resposta ou um erro.
 */
export const put = async (endpoint: string, data: Record<string, any>) => {
  try {
    const response = await api.put(endpoint, data);
    return response.data;
  } catch (error) {
    console.error('Erro ao realizar requisição PUT:', error);
    throw error;
  }
};

/**
 * Função para realizar uma requisição DELETE na API.
 * @param endpoint - O endpoint da API a ser acessado.
 * @returns Uma Promise com os dados da resposta ou um erro.
 */
export const remove = async (endpoint: string) => {
  try {
