import { useState, useEffect } from 'react';
import axios from 'axios';

interface Task {
  id: number;
  title: string;
  description: string;
  status: 'pending' | 'in-progress' | 'completed';
  assignedTo: string;
  dueDate: string;
}

/**
 * Hook para gerenciar tarefas.
 *
 * @returns {Object} - Retorna as tarefas, função para adicionar, atualizar e deletar tarefas.
 */
export const useTasks = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTasks();
  }, []);

  /**
   * Busca as tarefas do servidor.
   */
  const fetchTasks = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/v1/tasks');
      setTasks(response.data);
    } catch (err) {
      setError('Erro ao carregar tarefas.');
    } finally {
      setLoading(false);
    }
  };

  /**
   * Adiciona uma nova tarefa.
   *
   * @param {Task} task - A tarefa a ser adicionada.
   */
  const addTask = async (task: Task) => {
    try {
      const response = await axios.post('/api/v1/tasks', task);
      setTasks((prevTasks) => [...prevTasks, response.data]);
    } catch (err) {
      setError('Erro ao adicionar tarefa.');
    }
  };

  /**
   * Atualiza uma tarefa existente.
   *
   * @param {number} id - O ID da tarefa a ser atualizada.
   * @param {Partial<Task>} updatedTask - Os dados atualizados da tarefa.
   */
  const updateTask = async (id: number, updatedTask: Partial<Task>) => {
    try {
      const response = await axios.put(`/api/v1/tasks/${id}`, updatedTask);
      setTasks((prevTasks) =>
        prevTasks.map((task) => (task.id === id ? response.data : task))
      );
    } catch (err) {
      setError('Erro ao atualizar tarefa.');
    }
  };

  /**
   * Deleta uma tarefa.
   *
   * @param {number} id - O ID da tarefa a ser deletada.
   */
  const deleteTask = async (id: number) => {
    try {
      await axios.delete(`/api/v1/tasks/${id}`);
      setTasks((prevTasks) => prevTasks.filter((task) => task.id !== id));
    } catch (err) {
      setError('Erro ao deletar tarefa.');
    }
  };

  return { tasks, loading, error, addTask, updateTask, deleteTask };
};

