import { z } from 'zod';

/**
 * Classe que representa uma Lista Ligada Simples.
 * 
 * @class LinkedList
 */
class LinkedList<T> {
  private head: ListNode<T> | null;
  private size: number;

  constructor() {
    this.head = null;
    this.size = 0;
  }

  /**
   * Adiciona um novo nó ao final da lista.
   * 
   * @param {T} value - O valor a ser adicionado.
   */
  add(value: T): void {
    const newNode = new ListNode(value);
    if (!this.head) {
      this.head = newNode;
    } else {
      let current = this.head;
      while (current.next) {
        current = current.next;
      }
      current.next = newNode;
    }
    this.size++;
  }

  /**
   * Remove o nó com o valor especificado.
   * 
   * @param {T} value - O valor a ser removido.
   * @returns {boolean} - Retorna true se o nó foi removido, caso contrário, false.
   */
  remove(value: T): boolean {
    if (!this.head) return false;

    if (this.head.value === value) {
      this.head = this.head.next;
      this.size--;
      return true;
    }

    let current = this.head;
    while (current.next && current.next.value !== value) {
      current = current.next;
    }

    if (current.next) {
      current.next = current.next.next;
      this.size--;
      return true;
    }

    return false;
  }

  /**
   * Retorna o tamanho da lista.
   * 
   * @returns {number} - O número de elementos na lista.
   */
  getSize(): number {
    return this.size;
  }

  /**
   * Verifica se a lista está vazia.
   * 
   * @returns {boolean} - Retorna true se a lista estiver vazia, caso contrário, false.
   */
  isEmpty(): boolean {
    return this.size === 0;
  }

  /**
   * Limpa a lista, removendo todos os nós.
   */
  clear(): void {
    this.head = null;
    this.size = 0;
  }

  /**
   * Retorna uma representação em string da lista.
   * 
   * @returns {string} - A representação em string da lista.
   */
  toString(): string {
    if (!this.head) return '';

    let result = '';
    let current = this.head;
    while (current) {
      result += `${current.value} -> `;
      current = current.next;
    }
    return result.slice(0, -4);
  }
}

