/**
 * Classe que representa um Vetor (Array) com operações básicas e avançadas.
 */
class ArrayStructure<T> {
  private array: T[];

  constructor() {
    this.array = [];
  }

  /**
   * Insere um elemento no final do vetor.
   * @param element - Elemento a ser inserido.
   */
  insert(element: T): void {
    this.array.push(element);
  }

  /**
   * Remove o último elemento do vetor.
   * @returns O elemento removido ou undefined se o vetor estiver vazio.
   */
  remove(): T | undefined {
    return this.array.pop();
  }

  /**
   * Busca um elemento no vetor.
   * @param element - Elemento a ser buscado.
   * @returns O índice do elemento ou -1 se não encontrado.
   */
  search(element: T): number {
    return this.array.indexOf(element);
  }

  /**
   * Atualiza o elemento em um índice específico.
   * @param index - Índice do elemento a ser atualizado.
   * @param element - Novo valor do elemento.
   */
  update(index: number, element: T): void {
    if (index >= 0 && index < this.array.length) {
      this.array[index] = element;
    } else {
      throw new Error('Índice fora do intervalo.');
    }
  }

  /**
   * Limpa todos os elementos do vetor.
   */
  clear(): void {
    this.array = [];
  }

  /**
   * Obtém o tamanho do vetor.
   * @returns O número de elementos no vetor.
   */
  size(): number {
    return this.array.length;
  }

  /**
   * Inverte a ordem dos elementos no vetor.
   */
  reverse(): void {
    this.array.reverse();
  }

  /**
   * Ordena os elementos do vetor.
   * @param compareFn - Função de comparação opcional.
   */
  sort(compareFn?: (a: T, b: T) => number): void {
    this.array.sort(compareFn);
  }

  /**
   * Encontra o valor mínimo no vetor.
   * @returns O valor mínimo ou undefined se o vetor estiver vazio.
   */
  findMin(): T | undefined {
    return this.array.length ? Math.min(...this.array as unknown as number[]) as unknown as T : undefined;
  }

  /**
   * Encontra o valor máximo no vetor.
   * @returns O valor máximo ou undefined se o vetor estiver vazio.
   */
  findMax(): T | undefined {
    return this.array.length ? Math.max(...this.array as unknown as number[]) as unknown as T : undefined;
  }

  /**
   * Concatena outro vetor ao vetor atual.
   * @param otherArray - Outro vetor a ser concatenado.
   */
  concatenate(otherArray: T[]): void {
    this.array = this.array.concat(otherArray);
  }

  /**
   * Valida se o índice está dentro do intervalo do vetor.
   * @param index - Índice a ser validado.
   */
  private validateIndex(index: number): void {
    const indexSchema = z.number().int().min(0).max(this.array.length - 1);
    indexSchema.parse(index);
  }
}

export default ArrayStructure;

