/**
 * Node of a Doubly Linked List
 * @template T - The type of the value stored in the node
 */
class DoublyLinkedListNode<T> {
  value: T;
  next: DoublyLinkedListNode<T> | null;
  prev: DoublyLinkedListNode<T> | null;

  /**
   * @param {T} value - The value to store in the node
   */
  constructor(value: T) {
    this.value = value;
    this.next = null;
    this.prev = null;
  }
}

/**
 * Doubly Linked List Data Structure
 * @template T - The type of the values stored in the list
 */
class DoublyLinkedList<T> {
  head: DoublyLinkedListNode<T> | null;
  tail: DoublyLinkedListNode<T> | null;
  length: number;

  constructor() {
    this.head = null;
    this.tail = null;
    this.length = 0;
  }

  /**
   * Inserts a new value at the end of the list
   * @param {T} value - The value to insert
   */
  append(value: T): void {
    const newNode = new DoublyLinkedListNode(value);
    if (!this.head) {
      this.head = newNode;
      this.tail = newNode;
    } else {
      if (this.tail) {
        this.tail.next = newNode;
        newNode.prev = this.tail;
        this.tail = newNode;
      }
    }
    this.length++;
  }

  /**
   * Inserts a new value at the beginning of the list
   * @param {T} value - The value to insert
   */
  prepend(value: T): void {
    const newNode = new DoublyLinkedListNode(value);
    if (!this.head) {
      this.head = newNode;
      this.tail = newNode;
    } else {
      newNode.next = this.head;
      this.head.prev = newNode;
      this.head = newNode;
    }
    this.length++;
  }

  /**
   * Removes the last element from the list
   * @returns {T | null} - The value of the removed element or null if the list is empty
   */
  removeLast(): T | null {
    if (!this.tail) return null;
    const removedValue = this.tail.value;
    if (this.head === this.tail) {
      this.head = null;
      this.tail = null;
    } else {
      if (this.tail.prev) {
        this.tail = this.tail.prev;
        this.tail.next = null;
      }
    }
    this.length--;
    return removedValue;
  }

  /**
   * Removes the first element from the list
   * @returns {T | null} - The value of the removed element or null if the list is empty
   */
  removeFirst(): T | null {
    if (!this.head) return null;
    const removedValue = this.head.value;
    if (this.head === this.tail) {
      this.head = null;
      this.tail = null;
    } else {
      if (this.head.next) {
        this.head = this.head.next;
        this.head.prev = null;
      }
    }
    this.length--;
    return removedValue;
  }

  /**
   * Finds a node by its value
   * @param {T} value - The value to search for
   * @returns {DoublyLinkedListNode<T> | null} - The node containing the value or null if not found
   */
  find(value: T): DoublyLinkedListNode<T> | null {
    let currentNode = this.head;
    while (currentNode) {
      if (currentNode.value === value) return currentNode;
      currentNode = currentNode.next;
    }
    return null;
  }

  /**
   * Converts the list to an array
   * @returns {T[]} - An array containing all the values in the list
   */
  toArray(): T[] {
    const array: T[] = [];
    let currentNode = this.head;
    while (currentNode) {
      array.push(currentNode.value);
      currentNode = currentNode.next;
    }
    return array;
  }

  /**
   * Clears the list
   */
  clear(): void {
    this.head = null;
    this.tail = null;
    this.length = 0;
  }

  /**
   * Gets the size of the list
   * @returns {number} - The number of elements in the list
   */
  size(): number {
    return this.length;
  }
}

export default DoublyLinkedList;

