/**
 * Classe que representa uma Árvore Binária de Busca (Binary Search Tree).
 * Fornece métodos para inserção, remoção, busca e outras operações comuns.
 */
class BinarySearchTree<T> {
  private root: TreeNode<T> | null = null;

  /**
   * Insere um novo valor na árvore.
   * @param value - O valor a ser inserido.
   */
  insert(value: T): void {
    const newNode = new TreeNode(value);
    if (this.root === null) {
      this.root = newNode;
    } else {
      this.insertNode(this.root, newNode);
    }
  }

  /**
   * Função auxiliar para inserir um nó na árvore.
   * @param node - O nó atual.
   * @param newNode - O novo nó a ser inserido.
   */
  private insertNode(node: TreeNode<T>, newNode: TreeNode<T>): void {
    if (newNode.value < node.value) {
      if (node.left === null) {
        node.left = newNode;
      } else {
        this.insertNode(node.left, newNode);
      }
    } else {
      if (node.right === null) {
        node.right = newNode;
      } else {
        this.insertNode(node.right, newNode);
      }
    }
  }

  /**
   * Busca um valor na árvore.
   * @param value - O valor a ser buscado.
   * @returns O nó encontrado ou null se não encontrado.
   */
  search(value: T): TreeNode<T> | null {
    return this.searchNode(this.root, value);
  }

  /**
   * Função auxiliar para buscar um nó na árvore.
   * @param node - O nó atual.
   * @param value - O valor a ser buscado.
   * @returns O nó encontrado ou null se não encontrado.
   */
  private searchNode(node: TreeNode<T> | null, value: T): TreeNode<T> | null {
    if (node === null) {
      return null;
    }
    if (value < node.value) {
      return this.searchNode(node.left, value);
    } else if (value > node.value) {
      return this.searchNode(node.right, value);
    } else {
      return node;
    }
  }

  /**
   * Remove um valor da árvore.
   * @param value - O valor a ser removido.
   */
  remove(value: T): void {
    this.root = this.removeNode(this.root, value);
  }

  /**
   * Função auxiliar para remover um nó da árvore.
   * @param node - O nó atual.
   * @param value - O valor a ser removido.
   * @returns O novo nó raiz após a remoção.
   */
  private removeNode(node: TreeNode<T> | null, value: T): TreeNode<T> | null {
    if (node === null) {
      return null;
    }
    if (value < node.value) {
      node.left = this.removeNode(node.left, value);
      return node;
    } else if (value > node.value) {
      node.right = this.removeNode(node.right, value);
      return node;
    } else {
      // Nó com apenas um filho ou nenhum
      if (node.left === null) {
        return node.right;
      } else if (node.right === null) {
        return node.left;
      }

      // Nó com dois filhos: obter o sucessor in-order (menor na subárvore direita)
      node.value = this.minValueNode(node.right).value;
      node.right = this.removeNode(node.right, node.value);
      return node;
    }
  }

  /**
   * Encontra o nó com o menor valor a partir de um nó dado.
   * @param node - O nó a partir do qual procurar o menor valor.
   * @returns O nó com o menor valor.
   */
  private minValueNode(node: TreeNode<T>): TreeNode<T> {
    let current = node;
    while (current.left !== null) {
      current = current.left;
    }
    return current;
  }
}

