/**
 * Classe que representa um Grafo.
 * Suporta operações em grafos direcionados/não-direcionados e ponderados/não-ponderados.
 */
class Graph {
  private adjacencyList: Map<string, Map<string, number>>;
  private isDirected: boolean;

  /**
   * Cria uma nova instância de um Grafo.
   * @param isDirected - Indica se o grafo é direcionado.
   */
  constructor(isDirected: boolean = false) {
    this.adjacencyList = new Map();
    this.isDirected = isDirected;
  }

  /**
   * Adiciona um vértice ao grafo.
   * @param vertex - O vértice a ser adicionado.
   */
  addVertex(vertex: string): void {
    if (!this.adjacencyList.has(vertex)) {
      this.adjacencyList.set(vertex, new Map());
    }
  }

  /**
   * Adiciona uma aresta entre dois vértices.
   * @param from - Vértice de origem.
   * @param to - Vértice de destino.
   * @param weight - Peso da aresta.
   */
  addEdge(from: string, to: string, weight: number = 1): void {
    if (!this.adjacencyList.has(from)) {
      this.addVertex(from);
    }
    if (!this.adjacencyList.has(to)) {
      this.addVertex(to);
    }
    this.adjacencyList.get(from)?.set(to, weight);
    if (!this.isDirected) {
      this.adjacencyList.get(to)?.set(from, weight);
    }
  }

  /**
   * Remove uma aresta entre dois vértices.
   * @param from - Vértice de origem.
   * @param to - Vértice de destino.
   */
  removeEdge(from: string, to: string): void {
    this.adjacencyList.get(from)?.delete(to);
    if (!this.isDirected) {
      this.adjacencyList.get(to)?.delete(from);
    }
  }

  /**
   * Remove um vértice e todas as suas arestas associadas.
   * @param vertex - O vértice a ser removido.
   */
  removeVertex(vertex: string): void {
    this.adjacencyList.delete(vertex);
    this.adjacencyList.forEach((edges) => {
      edges.delete(vertex);
    });
  }

  /**
   * Realiza uma busca em largura (BFS) a partir de um vértice inicial.
   * @param start - Vértice inicial.
   * @returns Lista de vértices na ordem de visitação.
   */
  bfs(start: string): string[] {
    const visited = new Set<string>();
    const queue: string[] = [start];
    const result: string[] = [];

    while (queue.length > 0) {
      const vertex = queue.shift()!;
      if (!visited.has(vertex)) {
        visited.add(vertex);
        result.push(vertex);
        this.adjacencyList.get(vertex)?.forEach((_, neighbor) => {
          if (!visited.has(neighbor)) {
            queue.push(neighbor);
          }
        });
      }
    }

    return result;
  }

  /**
   * Realiza uma busca em profundidade (DFS) a partir de um vértice inicial.
   * @param start - Vértice inicial.
   * @returns Lista de vértices na ordem de visitação.
   */
  dfs(start: string): string[] {
    const visited = new Set<string>();
    const result: string[] = [];

    const dfsHelper = (vertex: string) => {
      if (!visited.has(vertex)) {
        visited.add(vertex);
        result.push(vertex);
        this.adjacencyList.get(vertex)?.forEach((_, neighbor) => {
          dfsHelper(neighbor);
        });
      }
    };

    dfsHelper(start);
    return result;
  }

  /**
   * Encontra o caminho mais curto entre dois vértices usando o algoritmo de Dijkstra.
   * @param start - Vértice inicial.
   * @param end - Vértice final.
   * @returns O caminho mais curto e a distância total.
   */
  dijkstra(start: string, end: string): { path: string[]; distance: number } {
    const distances: Map<string, number> = new Map();
    const previous: Map<string, string | null> = new Map();
    const queue: Set<string> = new Set();

    this.adjacencyList.forEach((_, vertex) => {
      distances.set(vertex, Infinity);
      previous.set(vertex, null);
      queue.add(vertex);
    });
    distances.set(start, 0);

    while (queue.size > 0) {
      const current = Array.from(queue).reduce((minVertex, vertex) =>
        distances.get(vertex)! < distances.get(minVertex)!
          ? vertex
          : minVertex
      );

      if (current === end) {
        const path: string[] = [];
        let step: string | null = end;
        while (step) {
          path.unshift(step);
          step = previous.get(step) || null;
        }
        return { path, distance: distances.get(end)! };
      }

      queue.delete(current);

      this.adjacencyList.get(current)?.forEach((weight, neighbor) => {
        const alt = distances.get(current)! + weight;
        if (alt < distances.get(neighbor)!) {
          distances.set(neighbor, alt);
          previous.set(neighbor, current);
        }
      });
    }

    return { path: [], distance: Infinity };
  }
}

