/**
 * Testes para a estrutura de dados Lista Ligada Simples.
 */
describe('LinkedList', () => {
  it('deve inicializar uma lista vazia', () => {
    const list = new LinkedList();
    expect(list.size()).toBe(0);
    expect(list.isEmpty()).toBe(true);
  });

  it('deve adicionar um elemento no início da lista', () => {
    const list = new LinkedList<number>();
    list.addFirst(10);
    expect(list.size()).toBe(1);
    expect(list.getFirst()).toBe(10);
  });

  it('deve adicionar um elemento no final da lista', () => {
    const list = new LinkedList<number>();
    list.addLast(20);
    expect(list.size()).toBe(1);
    expect(list.getLast()).toBe(20);
  });

  it('deve remover o primeiro elemento da lista', () => {
    const list = new LinkedList<number>();
    list.addFirst(30);
    list.addFirst(40);
    const removed = list.removeFirst();
    expect(removed).toBe(40);
    expect(list.size()).toBe(1);
    expect(list.getFirst()).toBe(30);
  });

  it('deve remover o último elemento da lista', () => {
    const list = new LinkedList<number>();
    list.addLast(50);
    list.addLast(60);
    const removed = list.removeLast();
    expect(removed).toBe(60);
    expect(list.size()).toBe(1);
    expect(list.getLast()).toBe(50);
  });

  it('deve lançar erro ao remover de uma lista vazia', () => {
    const list = new LinkedList<number>();
    expect(() => list.removeFirst()).toThrow('A lista está vazia');
    expect(() => list.removeLast()).toThrow('A lista está vazia');
  });

  it('deve buscar um elemento na lista', () => {
    const list = new LinkedList<number>();
    list.addLast(70);
    list.addLast(80);
    expect(list.contains(70)).toBe(true);
    expect(list.contains(90)).toBe(false);
  });

  it('deve limpar a lista', () => {
    const list = new LinkedList<number>();
    list.addLast(100);
    list.addLast(110);
    list.clear();
    expect(list.size()).toBe(0);
    expect(list.isEmpty()).toBe(true);
  });
});

