import { describe, it, expect } from 'vitest';
import { ArrayDataStructure } from '../data-structures/ArrayDataStructure';

/**
 * Testes para a estrutura de dados Array.
 * Verifica operações básicas e avançadas, garantindo que a implementação
 * esteja correta e que os métodos retornem os resultados esperados.
 */
describe('ArrayDataStructure', () => {
  it('should insert an element at the end', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    expect(array.toArray()).toEqual([5]);
  });

  it('should remove an element by value', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    array.insert(10);
    array.remove(5);
    expect(array.toArray()).toEqual([10]);
  });

  it('should find an element by value', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    expect(array.find(5)).toBe(true);
    expect(array.find(10)).toBe(false);
  });

  it('should update an element at a specific index', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    array.update(0, 10);
    expect(array.toArray()).toEqual([10]);
  });

  it('should clear all elements', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    array.insert(10);
    array.clear();
    expect(array.toArray()).toEqual([]);
  });

  it('should return the correct size', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    array.insert(10);
    expect(array.size()).toBe(2);
  });

  it('should iterate over elements', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    array.insert(10);
    const elements = [];
    array.forEach((element) => elements.push(element));
    expect(elements).toEqual([5, 10]);
  });

  it('should reverse the array', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(5);
    array.insert(10);
    array.reverse();
    expect(array.toArray()).toEqual([10, 5]);
  });

  it('should sort the array', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(10);
    array.insert(5);
    array.sort();
    expect(array.toArray()).toEqual([5, 10]);
  });

  it('should find the minimum and maximum values', () => {
    const array = new ArrayDataStructure<number>();
    array.insert(10);
    array.insert(5);
    expect(array.min()).toBe(5);
    expect(array.max()).toBe(10);
  });
});

