type Node<T> = {
  value: T;
  next: Node<T> | null;
  prev: Node<T> | null;
};

class LinkedList<T> {
  private head: Node<T> | null = null;
  private tail: Node<T> | null = null;
  private length: number = 0;

  public insertNode(value: T, index: number): void {
    if (index < 0 || index > this.length) {
      throw new Error('Index out of bounds');
    }

    const newNode: Node<T> = { value, next: null, prev: null };

    if (index === 0) {
      if (this.head) {
        newNode.next = this.head;
        this.head.prev = newNode;
      }
      this.head = newNode;
      if (!this.tail) {
        this.tail = newNode;
      }
    } else if (index === this.length) {
      if (this.tail) {
        this.tail.next = newNode;
        newNode.prev = this.tail;
      }
      this.tail = newNode;
    } else {
      let current = this.head;
      for (let i = 0; i < index - 1; i++) {
        if (current) {
          current = current.next;
        }
      }
      if (current) {
        newNode.next = current.next;
        newNode.prev = current;
        if (current.next) {
          current.next.prev = newNode;
        }
        current.next = newNode;
      }
    }

    this.length++;
  }
}

import express from 'express';
import { Pool } from 'pg';
import { KafkaClient, Producer } from 'kafka-node';
import dotenv from 'dotenv';
import winston from 'winston';

dotenv.config();

interface IUsageContext {
  id: string;
  name: string;
  description: string;
}

interface IEventPayload {
  eventType: string;
  data: IUsageContext;
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

const kafkaClient = new KafkaClient({ kafkaHost: process.env.KAFKA_HOST });
const producer = new Producer(kafkaClient);

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
  ],
});

async function createUsageContext(contextData: IUsageContext): Promise<IUsageContext> {
  validateContextData(contextData);
  const createdContext = await insertIntoDatabase(contextData);
  await publishEventToKafka({ eventType: 'CONTEXT_CREATED', data: createdContext });
  return createdContext;
}

async function getUsageContext(contextId: string): Promise<IUsageContext> {
  const context = await fetchFromDatabase(contextId);
  if (!context) {
    throw new Error('Context not found');
  }
  return context;
}

function validateContextData(contextData: IUsageContext): void {
  if (!contextData.id || !contextData.name || !contextData.description) {
    throw new Error('Invalid context data');
  }
}

async function insertIntoDatabase(contextData: IUsageContext): Promise<IUsageContext> {
  const client = await pool.connect();
  try {
    const result = await client.query(
      'INSERT INTO usage_contexts (id, name, description) VALUES ($1, $2, $3) RETURNING *',
      [contextData.id, contextData.name, contextData.description]
    );
    return result.rows[0];
  } catch (error) {
    logger.error('Database insertion error', error);
    throw new Error('Failed to insert context into database');
  } finally {
    client.release();
  }
}

async function fetchFromDatabase(contextId: string): Promise<IUsageContext | null> {
  const client = await pool.connect();
  try {
    const result = await client.query('SELECT * FROM usage_contexts WHERE id = $1', [contextId]);
    return result.rows[0] || null;
  } catch (error) {
    logger.error('Database fetch error', error);
    throw new Error('Failed to fetch context from database');
  } finally {
    client.release();
  }
}

async function publishEventToKafka(eventPayload: IEventPayload): Promise<void> {
  return new Promise((resolve, reject) => {
    producer.send([
      { topic: 'usage-context-events', messages: JSON.stringify(eventPayload) }
    ], (err, data) => {
      if (err) {
        logger.error('Kafka publish error', err);
        reject(new Error('Failed to publish event to Kafka'));
      } else {
        resolve();
      }
    });
  });
}

