dotenv.config();

interface IPerformanceGoal {
  id: string;
  title: string;
  description: string;
  targetDate: Date;
  achieved: boolean;
}

interface IUserContext {
  userId: string;
  roles: string[];
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

const kafkaClient = new KafkaClient({ kafkaHost: process.env.KAFKA_HOST });
const producer = new Producer(kafkaClient);

async function createPerformanceGoal(goalData: IPerformanceGoal, userContext: IUserContext): Promise<IPerformanceGoal> {
  validatePerformanceGoal(goalData);
  checkUserPermissions(userContext, 'create');

  const client = await pool.connect();
  try {
    const result = await client.query(
      'INSERT INTO performance_goals (title, description, target_date, achieved) VALUES ($1, $2, $3, $4) RETURNING *',
      [goalData.title, goalData.description, goalData.targetDate, goalData.achieved]
    );
    const createdGoal = result.rows[0];

    publishEvent('performanceGoalCreated', createdGoal);

    return createdGoal;
  } catch (error) {
    throw new Error('Failed to create performance goal: ' + error.message);
  } finally {
    client.release();
  }
}

async function getPerformanceGoals(userContext: IUserContext): Promise<IPerformanceGoal[]> {
  checkUserPermissions(userContext, 'read');

  const client = await pool.connect();
  try {
    const result = await client.query('SELECT * FROM performance_goals');
    return result.rows;
  } catch (error) {
    throw new Error('Failed to retrieve performance goals: ' + error.message);
  } finally {
    client.release();
  }
}

async function updatePerformanceGoal(goalId: string, updates: Partial<IPerformanceGoal>, userContext: IUserContext): Promise<IPerformanceGoal> {
  validatePerformanceGoalUpdates(updates);
  checkUserPermissions(userContext, 'update');

  const client = await pool.connect();
  try {
    const result = await client.query(
      'UPDATE performance_goals SET title = $1, description = $2, target_date = $3, achieved = $4 WHERE id = $5 RETURNING *',
      [updates.title, updates.description, updates.targetDate, updates.achieved, goalId]
    );
    const updatedGoal = result.rows[0];

    publishEvent('performanceGoalUpdated', updatedGoal);

    return updatedGoal;
  } catch (error) {
    throw new Error('Failed to update performance goal: ' + error.message);
  } finally {
    client.release();
  }
}

async function deletePerformanceGoal(goalId: string, userContext: IUserContext): Promise<void> {
  checkUserPermissions(userContext, 'delete');

  const client = await pool.connect();
  try {
    await client.query('DELETE FROM performance_goals WHERE id = $1', [goalId]);

    publishEvent('performanceGoalDeleted', { id: goalId });
  } catch (error) {
    throw new Error('Failed to delete performance goal: ' + error.message);
  } finally {
    client.release();
  }
}

function validatePerformanceGoal(goalData: IPerformanceGoal): void {
  if (!goalData.title || !goalData.description || !goalData.targetDate) {
    throw new Error('Invalid performance goal data');
  }
}

function validatePerformanceGoalUpdates(updates: Partial<IPerformanceGoal>): void {
  if (updates.title === undefined && updates.description === undefined && updates.targetDate === undefined && updates.achieved === undefined) {
    throw new Error('No valid fields to update');
  }
}

function checkUserPermissions(userContext: IUserContext, action: string): void {
  if (!userContext.roles.includes('admin')) {
    throw new Error(`User does not have permission to ${action} performance goals`);
  }
}

function publishEvent(eventType: string, data: any): void {
  const payloads = [
    { topic: 'performance-goals', messages: JSON.stringify({ eventType, data }) }
  ];
  producer.send(payloads, (err, data) => {
    if (err) {
      console.error('Failed to publish event:', err);
    }
  });
}

