}

const client = new Client({
  connectionString: process.env.DATABASE_URL,
});
client.connect();

const kafkaClient = new KafkaClient({ kafkaHost: process.env.KAFKA_HOST });
const producer = new Producer(kafkaClient);

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
  ],
});

async function getFunctionalRequirements(req: Request, res: Response): Promise<void> {
  try {
    const userContext: IUserContext = req.body.userContext;
    if (!validateUserContext(userContext)) {
      res.status(403).send('Invalid user context');
      return;
    }

    const query = 'SELECT id, description FROM functional_requirements';
    const dbResponse = await client.query(query);
    const requirements: IRequirement[] = dbResponse.rows;

    res.status(200).json(requirements);

    const auditEvent: IEvent = {
      userId: userContext.userId,
      action: 'FETCH_REQUIREMENTS',
      timestamp: new Date(),
    };
    logAuditEvent(auditEvent);
  } catch (error) {
    logger.error('Error fetching functional requirements', error);
    res.status(500).send('Internal Server Error');
  }
}

function validateUserContext(userContext: IUserContext): boolean {
  if (!userContext.isAuthenticated) {
    throw new Error('User not authenticated');
  }
