const kafkaClient = new KafkaClient({ kafkaHost: process.env.KAFKA_HOST });
const producer = new Producer(kafkaClient);

const getApiDefinitions: IRequestHandler = async (req, res) => {
  try {
    // 1. Validar autenticação e autorização do usuário
    if (!req.isAuthenticated || !req.isAuthenticated()) {
      return res.status(401).json({ success: false, error: 'Unauthorized' });
    }

    // 2. Consultar definições de API no banco de dados
    const result = await pool.query('SELECT * FROM api_definitions');

    // 3. Formatar resposta conforme interface IApiResponse
    const response: IApiResponse = {
      success: true,
      data: result.rows,
    };

    // 4. Enviar resposta ao cliente
    res.json(response);
  } catch (error) {
    console.error('Error fetching API definitions:', error);
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
};

const updateApiDefinition: IRequestHandler = async (req, res) => {
  try {
    // 1. Validar autenticação e autorização do usuário
    if (!req.isAuthenticated || !req.isAuthenticated()) {
      return res.status(401).json({ success: false, error: 'Unauthorized' });
    }

    // 2. Validar payload de entrada
    const { id, definition } = req.body;
    if (!id || !definition) {
      return res.status(400).json({ success: false, error: 'Invalid input' });
    }

    // 3. Atualizar definição de API no banco de dados
    await pool.query('UPDATE api_definitions SET definition = $1 WHERE id = $2', [definition, id]);

    // 4. Publicar evento de atualização no Kafka
    const payloads = [{ topic: 'api-updates', messages: JSON.stringify({ id, definition }) }];
    producer.send(payloads, (err, data) => {
      if (err) {
        console.error('Error publishing to Kafka:', err);
      }
    });

    // 5. Enviar resposta de sucesso ao cliente
    res.json({ success: true });
  } catch (error) {
    console.error('Error updating API definition:', error);
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
};

