dotenv.config();

interface IUser {
  id: number;
  username: string;
  password: string;
  roles: IRole[];
}

interface IRole {
  id: number;
  name: string;
  permissions: IPermission[];
}

interface IPermission {
  id: number;
  name: string;
}

interface ITokenPayload {
  userId: number;
  username: string;
  roles: string[];
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL
});

const kafkaClient = new KafkaClient({ kafkaHost: process.env.KAFKA_HOST });
const producer = new Producer(kafkaClient);

async function authenticateUser(username: string, password: string): Promise<string> {
  const client = await pool.connect();
  try {
    const res = await client.query('SELECT * FROM users WHERE username = $1', [username]);
    if (res.rows.length === 0) {
      throw new Error('User not found');
    }
    const user: IUser = res.rows[0];
    const passwordMatch = await bcrypt.compare(password, user.password);
    if (!passwordMatch) {
      throw new Error('Invalid password');
    }
    const tokenPayload: ITokenPayload = {
      userId: user.id,
      username: user.username,
      roles: user.roles.map(role => role.name)
    };
    const token = jwt.sign(tokenPayload, process.env.JWT_SECRET!, { expiresIn: '1h' });
    return token;
  } finally {
    client.release();
  }
}

async function authorizeRequest(token: string, requiredPermissions: string[]): Promise<boolean> {
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET!) as ITokenPayload;
    const userPermissions = decoded.roles.flatMap(role => role.permissions.map(permission => permission.name));
    const hasPermissions = requiredPermissions.every(permission => userPermissions.includes(permission));
    if (!hasPermissions) {
      throw new Error('Insufficient permissions');
    }
    return true;
  } catch (error) {
    throw new Error('Invalid token or insufficient permissions');
  }
}

async function registerUser(userData: IUser): Promise<void> {
  const client = await pool.connect();
  try {
    const hashedPassword = await bcrypt.hash(userData.password, 10);
    await client.query('INSERT INTO users (username, password) VALUES ($1, $2)', [userData.username, hashedPassword]);
    const payloads = [{ topic: 'new-user', messages: JSON.stringify(userData) }];
    producer.send(payloads, (err, data) => {
      if (err) {
        throw new Error('Failed to publish user registration event');
      }
    });
  } finally {
    client.release();
  }
}

