function encryptData(data: string): string {
  try {
    const cipher = crypto.createCipher('aes-256-cbc', 'your_secret_key');
    let encrypted = cipher.update(data, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return encrypted;
  } catch (error) {
    throw new Error('Encryption failed');
  }
}

