        const startTime = Date.now();
        const response = await request(app)[scenario.method.toLowerCase()](scenario.endpoint);
        const endTime = Date.now();

        // Step 5: Collect performance metrics using Prometheus
        const responseTime = endTime - startTime;
        responseTimeGauge.set(responseTime);

        // Step 6: Validate results against defined performance goals
        try {
          expect(responseTime).to.be.below(scenario.expectedResponseTime);
        } catch (error) {
