import { KafkaClient, Producer } from 'kafka-node';
import express from 'express';

interface IDataModel {
  id: string;
  data: any;
  validate(): boolean;
  save(): Promise<void>;
}

interface IEvent {
  type: string;
  payload: any;
}

class DataModel implements IDataModel {
  id: string;
  data: any;

  constructor(id: string, data: any) {
    this.id = id;
    this.data = data;
  }

  validate(): boolean {
    // Implementação de validação
    return this.data !== null && typeof this.data === 'object';
  }

  async save(): Promise<void> {
    const client = new Client();
    await client.connect();
    try {
      await client.query('INSERT INTO data_models (id, data) VALUES ($1, $2)', [this.id, this.data]);
    } finally {
      await client.end();
    }
  }
}

const kafkaClient = new KafkaClient();
const producer = new Producer(kafkaClient);

function publishEvent(event: IEvent): Promise<void> {
  return new Promise((resolve, reject) => {
    producer.send([{ topic: 'events', messages: JSON.stringify(event) }], (err) => {
      if (err) reject(err);
      else resolve();
    });
  });
}

async function testDataModelCreation(): Promise<void> {
  const dataModel = new DataModel('1', { key: 'value' });

  if (!dataModel.validate()) {
    throw new Error('DataModel validation failed');
  }

  await dataModel.save();

  const client = new Client();
  await client.connect();
  try {
    const res = await client.query('SELECT * FROM data_models WHERE id = $1', ['1']);
    if (res.rows.length === 0) {
      throw new Error('Data not persisted in database');
    }
  } finally {
    await client.end();
  }

  const event: IEvent = { type: 'DataModelCreated', payload: dataModel };
  await publishEvent(event);
}

async function testDataModelValidation(): Promise<void> {
  const dataModel = new DataModel('2', null);

  try {
    if (dataModel.validate()) {
      throw new Error('Validation should have failed');
    }
    await dataModel.save();
  } catch (error) {
    if (error.message !== 'DataModel validation failed') {
      throw new Error('Unexpected error during validation');
    }
  }

  const event: IEvent = { type: 'DataModelCreated', payload: dataModel };
  try {
    await publishEvent(event);
    throw new Error('Event should not be published');
  } catch (error) {
    if (error.message !== 'Event should not be published') {
      // Expected behavior, do nothing
    } else {
      throw error;
    }
  }
}

describe('DataModel Tests', () => {
  it('should create and persist a valid DataModel', async () => {
    await testDataModelCreation();
  });

  it('should fail to validate and persist an invalid DataModel', async () => {
    await testDataModelValidation();
  });
});

