import request from 'supertest';
import express from 'express';
import jwt from 'jsonwebtoken';
import dotenv from 'dotenv';

dotenv.config();

const app = express();

// Middleware de autenticação
function authenticationMiddleware(req, res, next) {
  const token = req.headers['authorization'];
  if (!token) return res.status(401).send('Access Denied');
  try {
    const verified = jwt.verify(token, process.env.TOKEN_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid Token');
  }
}

// Middleware de autorização
function authorizationMiddleware(req, res, next) {
  if (req.user.role !== 'admin') return res.status(403).send('Forbidden');
  next();
}

// Rota de teste para autenticação
app.get('/test-auth', authenticationMiddleware, (req, res) => {
  res.send('Authenticated');
});

// Rota de teste para autorização
app.get('/test-authz', authenticationMiddleware, authorizationMiddleware, (req, res) => {
  res.send('Authorized');
});

// Função de teste para middleware de autenticação
function testAuthenticationMiddleware() {
  describe('Authentication Middleware', () => {
    it('should return 401 if no token is provided', async () => {
      const response = await request(app).get('/test-auth');
      expect(response.status).toBe(401);
      expect(response.text).toBe('Access Denied');
    });

    it('should return 400 if token is invalid', async () => {
      const response = await request(app)
        .get('/test-auth')
        .set('Authorization', 'invalidtoken');
      expect(response.status).toBe(400);
      expect(response.text).toBe('Invalid Token');
    });

    it('should return 200 if token is valid', async () => {
      const token = jwt.sign({ id: 1 }, process.env.TOKEN_SECRET);
      const response = await request(app)
        .get('/test-auth')
        .set('Authorization', token);
      expect(response.status).toBe(200);
      expect(response.text).toBe('Authenticated');
    });
  });
}

// Função de teste para middleware de autorização
function testAuthorizationMiddleware() {
  describe('Authorization Middleware', () => {
    it('should return 403 if user does not have permission', async () => {
      const token = jwt.sign({ id: 1, role: 'user' }, process.env.TOKEN_SECRET);
      const response = await request(app)
        .get('/test-authz')
        .set('Authorization', token);
      expect(response.status).toBe(403);
      expect(response.text).toBe('Forbidden');
    });

    it('should return 200 if user has permission', async () => {
      const token = jwt.sign({ id: 1, role: 'admin' }, process.env.TOKEN_SECRET);
      const response = await request(app)
        .get('/test-authz')
        .set('Authorization', token);
      expect(response.status).toBe(200);
      expect(response.text).toBe('Authorized');
    });
  });
}

// Função de teste para criptografia de dados
function testDataEncryption() {
  const crypto = require('crypto');
  const algorithm = 'aes-256-cbc';
  const key = crypto.randomBytes(32);
  const iv = crypto.randomBytes(16);

  function encrypt(text) {
    const cipher = crypto.createCipheriv(algorithm, Buffer.from(key), iv);
    let encrypted = cipher.update(text);
    encrypted = Buffer.concat([encrypted, cipher.final()]);
    return { iv: iv.toString('hex'), encryptedData: encrypted.toString('hex') };
  }

  function decrypt(text) {
    const iv = Buffer.from(text.iv, 'hex');
    const encryptedText = Buffer.from(text.encryptedData, 'hex');
    const decipher = crypto.createDecipheriv(algorithm, Buffer.from(key), iv);
    let decrypted = decipher.update(encryptedText);
    decrypted = Buffer.concat([decrypted, decipher.final()]);
    return decrypted.toString();
  }

  describe('Data Encryption', () => {
    it('should encrypt and decrypt data correctly', () => {
      const data = 'Sensitive Data';
      const encrypted = encrypt(data);
      const decrypted = decrypt(encrypted);
      expect(decrypted).toBe(data);
    });
  });
}

testAuthenticationMiddleware();
testAuthorizationMiddleware();
testDataEncryption();

