    const docker = new Docker();
    for (const service of config.dockerServices) {
      await docker.createContainer({ Image: service }).then(container => container.start());
    }

    const pgClient = new PgClient(config.postgresConfig.connectionString);
    await pgClient.connect();

    const kafkaClient = new KafkaClient({ clientId: config.kafkaConfig.clientId, kafkaHost: config.kafkaConfig.brokers.join(',') });
    const producer = new Producer(kafkaClient);
    await new Promise((resolve, reject) => producer.on('ready', resolve).on('error', reject));

    const prometheusGauge = new Gauge({ name: 'test_gauge', help: 'Test gauge' });
    register.registerMetric(prometheusGauge);

    const grafana = new GrafanaApi({ url: config.grafanaConfig.url, token: config.grafanaConfig.apiKey });
    await grafana.createDashboard({ dashboard: { title: 'Test Dashboard' } });

    await apply({ dir: config.terraformConfig.directory });
  } catch (error) {
    throw new Error(`Failed to setup test environment: ${error.message}`);
  }
}

async function teardownTestEnvironment(config: ITestConfig): Promise<void> {
  try {
    const docker = new Docker();
    for (const service of config.dockerServices) {
      const container = docker.getContainer(service);
      await container.stop();
      await container.remove();
    }

    const pgClient = new PgClient(config.postgresConfig.connectionString);
    await pgClient.connect();
    await pgClient.query('DELETE FROM test_data');
    await pgClient.end();

    const kafkaClient = new KafkaClient({ clientId: config.kafkaConfig.clientId, kafkaHost: config.kafkaConfig.brokers.join(',') });
    const producer = new Producer(kafkaClient);
    await new Promise((resolve, reject) => producer.on('ready', resolve).on('error', reject));
    producer.close();

    await destroy({ dir: config.terraformConfig.directory });
  } catch (error) {
    throw new Error(`Failed to teardown test environment: ${error.message}`);
  }
}

function testInfrastructureProvisioning(config: ITestConfig): void {
