    while (retryCount < maxRetries) {
      try {
        await kafkaService.sendMessage('test');
        break;
      } catch (error) {
        retryCount++;
        if (retryCount >= maxRetries) {
          throw error;
        }
      }
    }

    expect(retryCount).toBeLessThanOrEqual(maxRetries);
  } catch (error) {
    console.error('Resilience and fault tolerance test failed:', error);
    throw error;
  }
}

