async function testApiEndpoint(app: INestApplication, endpoint: string, method: string, payload: any, expectedStatus: number): Promise<void> {
  try {
    let response;
    switch (method.toUpperCase()) {
      case 'GET':
        response = await request(app.getHttpServer()).get(endpoint);
        break;
      case 'POST':
        response = await request(app.getHttpServer()).post(endpoint).send(payload);
        break;
      case 'PUT':
        response = await request(app.getHttpServer()).put(endpoint).send(payload);
        break;
      case 'DELETE':
        response = await request(app.getHttpServer()).delete(endpoint);
        break;
      default:
        throw new Error(`Unsupported HTTP method: ${method}`);
    }
    if (response.status !== expectedStatus) {
      console.error(`Expected status ${expectedStatus}, but got ${response.status}`);
      throw new Error('Response status does not match expected status');
    }
    console.log('Response:', response.body);
  } catch (error) {
    console.error('Error testing API endpoint:', error);
    throw error;
  }
}

async function testKafkaIntegration(kafkaService: KafkaService, topic: string, message: any, expectedResponse: any): Promise<void> {
  try {
    await kafkaService.sendMessage(topic, message);
    const response = await kafkaService.listenForResponse(topic);
    if (JSON.stringify(response) !== JSON.stringify(expectedResponse)) {
      console.error(`Expected response ${JSON.stringify(expectedResponse)}, but got ${JSON.stringify(response)}`);
      throw new Error('Kafka response does not match expected response');
    }
    console.log('Kafka interaction successful:', response);
  } catch (error) {
    console.error('Error testing Kafka integration:', error);
    throw error;
  }
}

async function testRedisCache(redisService: RedisService, key: string, expectedValue: any): Promise<void> {
  try {
