    .get('/tenant1/resource')
    .set('Authorization', `Bearer ${tenant1Token}`)
    .expect(200);

  // Test tenant 2 access
  await request(app.getHttpServer())
    .get('/tenant2/resource')
    .set('Authorization', `Bearer ${tenant2Token}`)
    .expect(200);

