    kafkaService = module.get<KafkaService>(KafkaService);
    redisService = module.get<RedisService>(RedisService);
  });

  it('shouldRetryOnFailure', () => {
    // Simulate a failure in a dependent service
    jest.spyOn(kafkaService, 'sendMessage').mockImplementation(() => {
      throw new Error('Simulated failure');
    });

    // Invoke the method that should retry on failure
    const retrySpy = jest.spyOn(retry, 'execute');
    try {
      resilienceService.sendMessageWithRetry();
    } catch (e) {}

    // Assert that the retry logic is triggered the expected number of times
    expect(retrySpy).toHaveBeenCalledTimes(3); // Assuming 3 retries
  });

  it('shouldBackoffOnConsecutiveFailures', () => {
    // Simulate consecutive failures in a dependent service
    jest.spyOn(redisService, 'getData').mockImplementation(() => {
      throw new Error('Simulated failure');
    });

    // Invoke the method that should implement backoff strategy
    const backoffSpy = jest.spyOn(backoff, 'execute');
    try {
      resilienceService.getDataWithBackoff();
    } catch (e) {}

    // Assert that the backoff delay increases as expected with each failure
    expect(backoffSpy).toHaveBeenCalledTimes(3); // Assuming 3 backoffs
  });

  it('shouldOpenCircuitBreakerOnThreshold', () => {
    // Initialize the ResilienceService with a CircuitBreaker instance
    const circuitBreaker = new CircuitBreaker(() => {
      throw new Error('Simulated failure');
    }, { errorThresholdPercentage: 50, resetTimeout: 10000 });

    // Simulate failures to reach the threshold for opening the circuit
    for (let i = 0; i < 5; i++) {
      try {
        circuitBreaker.fire();
      } catch (e) {}
    }

    // Assert that the circuit breaker opens after the threshold is reached
    expect(circuitBreaker.opened).toBe(true);
  });

  it('shouldCloseCircuitBreakerAfterTimeout', (done) => {
    // Initialize the ResilienceService with a CircuitBreaker instance
    const circuitBreaker = new CircuitBreaker(() => {
      throw new Error('Simulated failure');
    }, { errorThresholdPercentage: 50, resetTimeout: 1000 });

    // Simulate the circuit breaker opening due to failures
    for (let i = 0; i < 5; i++) {
      try {
        circuitBreaker.fire();
      } catch (e) {}
    }

    // Wait for the timeout period to elapse
    setTimeout(() => {
      // Assert that the circuit breaker closes after the timeout period
      expect(circuitBreaker.closed).toBe(true);
      done();
    }, 1500);
  });

  it('shouldHandlePartialFailuresGracefully', () => {
    // Simulate partial failures in a dependent service
    jest.spyOn(kafkaService, 'sendMessage').mockImplementationOnce(() => {
      throw new Error('Simulated partial failure');
    });

    // Invoke the method that should handle partial failures
    const logSpy = jest.spyOn(console, 'log');
    resilienceService.sendMessageWithPartialFailureHandling();

    // Assert that the system continues to function and logs the partial failures
    expect(logSpy).toHaveBeenCalledWith('Partial failure occurred');
  });
});

