      expect(output).to.not.include('error');
    } catch (error) {
      expect.fail(`Type-check stage failed: ${error.message}`);
    }
  });

  it('should pass the unit tests stage', () => {
    try {
      const output = executeCommand('npm test');
      expect(output).to.include('passing');
    } catch (error) {
      expect.fail(`Unit tests stage failed: ${error.message}`);
    }
  });

  it('should pass the integration tests stage', () => {
    try {
      const output = executeCommand('npm run test:integration');
      expect(output).to.include('passing');
    } catch (error) {
      expect.fail(`Integration tests stage failed: ${error.message}`);
    }
  });

  it('should pass the security validation stage', () => {
    try {
      const output = executeCommand('npm run security-check');
      expect(output).to.not.include('vulnerabilities');
    } catch (error) {
      expect.fail(`Security validation stage failed: ${error.message}`);
    }
  });

  it('should generate artifacts successfully', () => {
    try {
      executeCommand('npm run build');
      const artifactPath = join(__dirname, '../dist');
