import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Actor } from '../entities/Actor.entity';
import { CreateActorDto } from '../dto/CreateActor.dto';
import { UpdateActorDto } from '../dto/UpdateActor.dto';
import { EventEmitter2 } from '@nestjs/event-emitter';

interface IActorService {
  createActor(data: CreateActorDto): Promise<Actor>;
  updateActor(id: string, data: UpdateActorDto): Promise<Actor>;
  deleteActor(id: string): Promise<void>;
  getActorById(id: string): Promise<Actor>;
  listActors(tenantId: string): Promise<Actor[]>;
}

@Injectable()
class ActorService implements IActorService {
  constructor(
    @InjectRepository(Actor)
    private readonly actorRepository: Repository<Actor>,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async createActor(data: CreateActorDto): Promise<Actor> {
    // Validate input data using DTO
    const existingActor = await this.actorRepository.findOne({ where: { uniqueIdentifier: data.uniqueIdentifier } });
    if (existingActor) {
      throw new Error('ActorExistsError');
    }
    const actor = this.actorRepository.create(data);
    const savedActor = await this.actorRepository.save(actor);
    this.eventEmitter.emit('actor.created', savedActor);
    return savedActor;
  }

  async updateActor(id: string, data: UpdateActorDto): Promise<Actor> {
    const actor = await this.actorRepository.findOne(id);
    if (!actor) {
      throw new Error('ActorNotFoundError');
    }
    this.actorRepository.merge(actor, data);
    const updatedActor = await this.actorRepository.save(actor);
    this.eventEmitter.emit('actor.updated', updatedActor);
    return updatedActor;
  }

  async deleteActor(id: string): Promise<void> {
    const actor = await this.actorRepository.findOne(id);
    if (!actor) {
      throw new Error('ActorNotFoundError');
    }
    await this.actorRepository.remove(actor);
    this.eventEmitter.emit('actor.deleted', id);
  }

  async getActorById(id: string): Promise<Actor> {
    const actor = await this.actorRepository.findOne(id);
    if (!actor) {
      throw new Error('ActorNotFoundError');
    }
    return actor;
  }

  async listActors(tenantId: string): Promise<Actor[]> {
    try {
      return await this.actorRepository.find({ where: { tenantId } });
    } catch (error) {
      throw new Error('DatabaseConnectionError');
    }
  }
}

