import { z } from 'zod';

interface ISystemLimitations {
  maxUsers: number;
  maxRequestsPerMinute: number;
  maxDataStorage: number;
  validateLimits(): boolean;
}

class LimitExceededError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'LimitExceededError';
  }
}

class SystemLimitations implements ISystemLimitations {
  maxUsers: number;
  maxRequestsPerMinute: number;
  maxDataStorage: number;

  constructor(maxUsers: number, maxRequestsPerMinute: number, maxDataStorage: number) {
    this.maxUsers = maxUsers;
    this.maxRequestsPerMinute = maxRequestsPerMinute;
    this.maxDataStorage = maxDataStorage;
  }

  validateLimits(): boolean {
    return this.maxUsers > 0 && this.maxRequestsPerMinute > 0 && this.maxDataStorage > 0;
  }

  checkUserLimit(currentUsers: number): boolean {
    if (currentUsers > this.maxUsers) {
      throw new LimitExceededError('User limit exceeded');
    }
    return true;
  }

  checkRequestLimit(currentRequests: number): boolean {
    if (currentRequests > this.maxRequestsPerMinute) {
      throw new LimitExceededError('Request limit exceeded');
    }
    return true;
  }

  checkDataStorageLimit(currentDataStorage: number): boolean {
    if (currentDataStorage > this.maxDataStorage) {
      throw new LimitExceededError('Data storage limit exceeded');
    }
    return true;
  }
}

// Example usage
const systemLimits = new SystemLimitations(1000, 5000, 10000);
try {
  systemLimits.checkUserLimit(900);
  systemLimits.checkRequestLimit(4500);
  systemLimits.checkDataStorageLimit(9500);
} catch (error) {
  if (error instanceof LimitExceededError) {
    console.error(error.message);
  }
}

