// Define the schema for validation using zod
const decisionSchema = z.object({
  id: z.string(),
  description: z.string(),
  decisionDate: z.date(),
  status: z.string(),
  impact: z.string()
});

// Define the interface for architectural decisions
interface IArchitecturalDecision {
  id: string;
  description: string;
  decisionDate: Date;
  status: string;
  impact: string;
  evaluateImpact(): string;
}

// Custom error for existing decisions
class DecisionExistsError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DecisionExistsError';
  }
}

// Mock database
const database: IArchitecturalDecision[] = [];

// Function to record a new architectural decision
async function recordDecision(decision: IArchitecturalDecision): Promise<void> {
  // Step 1: Validate the decision input using zod schema
  decisionSchema.parse(decision);

  // Step 2: Check if a similar decision already exists
  const existingDecision = database.find(d => d.id === decision.id);
  if (existingDecision) {
    throw new DecisionExistsError('A decision with this ID already exists.');
  }

  // Step 3: If not, save the decision to the database
  database.push(decision);

  // Step 4: Log the decision for audit purposes
  console.log('Decision recorded:', decision);
}

// Function to get architectural decisions based on a filter
async function getDecisions(filter: { status?: string, impact?: string }): Promise<IArchitecturalDecision[]> {
  try {
    // Step 1: Validate the filter input
    const filterSchema = z.object({
      status: z.string().optional(),
      impact: z.string().optional()
    });
    filterSchema.parse(filter);

    // Step 2: Query the database for decisions matching the filter
    const filteredDecisions = database.filter(decision => {
      return (!filter.status || decision.status === filter.status) &&
             (!filter.impact || decision.impact === filter.impact);
    });

    // Step 3: Return the list of decisions
    return filteredDecisions;
  } catch (error) {
    // Handle database connection errors gracefully
    console.error('Error fetching decisions:', error);
    throw new Error('Failed to fetch decisions. Please try again later.');
  }
}

