    const orderSchema = z.object({
      orderId: z.string(),
      userId: z.string(),
      amount: z.number().positive()
    });
    orderSchema.parse(orderData);

    await this.pgClient.connect();
    const userRes = await this.pgClient.query('SELECT balance FROM users WHERE id = $1', [orderData.userId]);
    if (userRes.rows.length === 0 || userRes.rows[0].balance < orderData.amount) {
      throw new InsufficientFundsError('Insufficient funds');
    }

    await this.pgClient.query('UPDATE users SET balance = balance - $1 WHERE id = $2', [orderData.amount, orderData.userId]);
    await this.pgClient.query('INSERT INTO orders (orderId, userId, amount) VALUES ($1, $2, $3)', [orderData.orderId, orderData.userId, orderData.amount]);

    const producer = this.kafka.producer();
    await producer.connect();
    await producer.send({
      topic: 'order-processed',
      messages: [{ key: orderData.orderId, value: JSON.stringify(orderData) }]
    });
    await producer.disconnect();

