  constructor(message: string) {
    super(message);
    this.name = 'RequirementNotFoundError';
  }
}

const database: INonFunctionalRequirement[] = [];

async function addNonFunctionalRequirement(requirement: INonFunctionalRequirement): Promise<void> {
  if (!requirement.validate()) {
    throw new Error('Invalid requirement');
  }

  const exists = database.some(r => r.id === requirement.id);
  if (exists) {
    throw new RequirementExistsError(`Requirement with ID ${requirement.id} already exists.`);
  }

  database.push(requirement);
  console.log(`Added requirement with ID: ${requirement.id}`);
}

async function updateNonFunctionalRequirement(id: string, updates: Partial<INonFunctionalRequirement>): Promise<void> {
  const requirementIndex = database.findIndex(r => r.id === id);
  if (requirementIndex === -1) {
    throw new RequirementNotFoundError(`Requirement with ID ${id} not found.`);
  }

  const updatedRequirement = { ...database[requirementIndex], ...updates };
  if (!updatedRequirement.validate()) {
    throw new Error('Invalid updated requirement');
  }

  database[requirementIndex] = updatedRequirement;
  console.log(`Updated requirement with ID: ${id}`);
}

async function deleteNonFunctionalRequirement(id: string): Promise<void> {
  const requirementIndex = database.findIndex(r => r.id === id);
  if (requirementIndex === -1) {
    throw new RequirementNotFoundError(`Requirement with ID ${id} not found.`);
  }

  database.splice(requirementIndex, 1);
  console.log(`Deleted requirement with ID: ${id}`);
}

