interface IMessagePayload {
  eventType: string;
  data: any;
}

interface IEventHandler {
  handleEvent(payload: IMessagePayload): Promise<void>;
}

const messagePayloadSchema = z.object({
  eventType: z.string(),
  data: z.any()
});

@Injectable()
class AsynchronousContracts {
  private kafka = new Kafka({
    clientId: 'my-app',
    brokers: ['kafka-broker:9092']
  });

  async sendMessage(topic: string, message: IMessagePayload): Promise<void> {
    try {
      messagePayloadSchema.parse(message);
      const producer = this.kafka.producer();
      await producer.connect();
      await producer.send({
        topic,
        messages: [{ value: JSON.stringify(message) }]
      });
      await producer.disconnect();
    } catch (error) {
      console.error('Error sending message:', error);
      // Implement exponential backoff retry logic here
    }
  }

  async consumeMessages(topic: string, handler: IEventHandler): Promise<void> {
    const consumer = this.kafka.consumer({ groupId: 'my-group' });
    try {
      await consumer.connect();
      await consumer.subscribe({ topic, fromBeginning: true });
      await consumer.run({
        eachMessage: async ({ message }) => {
          try {
            const payload: IMessagePayload = JSON.parse(message.value.toString());
            await handler.handleEvent(payload);
            await consumer.commitOffsets([{ topic, partition: message.partition, offset: (Number(message.offset) + 1).toString() }]);
          } catch (error) {
