interface IRequest {
  id: string;
  data: any;
  timestamp: Date;
  validate(): boolean;
}

interface IResponse {
  status: string;
  message: string;
  data?: any;
  format(): IResponse;
}

@Controller('synchronous')
@ApiTags('Synchronous APIs')
export class SynchronousController {
  constructor(private readonly synchronousService: SynchronousService) {}

  @Post('handle')
  @ApiOperation({ summary: 'Handle a synchronous request' })
  @ApiResponse({ status: 201, description: 'The request has been successfully processed.', type: RequestResponseDto })
  @ApiResponse({ status: 400, description: 'Invalid request data.' })
  async handleRequest(@Body() createRequestDto: CreateRequestDto): Promise<IResponse> {
    const request: IRequest = {
      id: createRequestDto.id,
      data: createRequestDto.data,
      timestamp: new Date(),
      validate: function (): boolean {
        // Basic validation logic
        return !!this.id && !!this.data;
      }
    };

    if (!request.validate()) {
      throw new Error('Validation failed: Invalid request data.');
    }

    try {
      const processedData = await this.synchronousService.process(request.data);
      const response: IResponse = {
        status: 'success',
        message: 'Request processed successfully.',
        data: processedData,
        format: function (): IResponse {
          return this;
        }
      };
      return response.format();
    } catch (error) {
      throw new Error('Processing failed: ' + error.message);
    }
  }
}

