function getKafkaConfig(configService: ConfigService): IKafkaConfig {
  const clientId = configService.get<string>('KAFKA_CLIENT_ID');
  const brokers = configService.get<string[]>('KAFKA_BROKERS');

  if (!clientId || !brokers || brokers.length === 0) {
    throw new Error('Missing Kafka configuration');
  }

  return { clientId, brokers };
}

export class FolderStructure {
  private structure: Record<string, any>;

  constructor() {
    this.structure = {};
  }

  public addFolder(path: string): void {
    const parts = path.split('/');
    let current = this.structure;
    for (const part of parts) {
      if (!current[part]) {
        current[part] = {};
      }
      current = current[part];
    }
  }

  public removeFolder(path: string): void {
    const parts = path.split('/');
    let current = this.structure;
    const stack = [];
    for (const part of parts) {
      if (!current[part]) {
        return;
      }
      stack.push([current, part]);
      current = current[part];
    }
    while (stack.length) {
      const [parent, part] = stack.pop();
      delete parent[part];
      if (Object.keys(parent).length > 0) {
        break;
      }
    }
  }

  public listFolders(): string[] {
    const result: string[] = [];
    const traverse = (node: Record<string, any>, path: string) => {
      for (const key in node) {
        const newPath = path ? path + '/' + key : key;
        result.push(newPath);
        traverse(node[key], newPath);
      }
    };
    traverse(this.structure, '');
    return result;
  }
}

