async function executePipeline(config: ICICDPipelineConfig): Promise<void> {
  if (!config.validateConfig()) {
    throw new Error('Invalid pipeline configuration');
  }

  for (const stage of config.stages) {
    try {
      // Set environment variables
      for (const [key, value] of Object.entries(stage.environment.variables)) {
        process.env[key] = value;
      }

      // Execute commands
      for (const command of stage.commands) {
        const { stdout, stderr } = await execAsync(command);
        console.log(`Output: ${stdout}`);
        if (stderr) {
          console.error(`Error: ${stderr}`);
          throw new Error(`Command failed: ${command}`);
        }
      }
    } catch (error) {
      console.error(`Stage failed: ${stage.name}`);
      if (config.notifications) {
        await sendNotification(config.notifications, `Stage failed: ${stage.name}`);
      }
      break;
    }
  }
}

