// Define the configuration schema using zod
const InfrastructureConfigSchema = z.object({
  nodeVersion: z.string().nonempty(),
  typescriptVersion: z.string().nonempty(),
  nestjsVersion: z.string().nonempty(),
  postgresVersion: z.string().nonempty(),
  kafkaVersion: z.string().nonempty(),
  dockerVersion: z.string().nonempty(),
  kubernetesVersion: z.string().nonempty()
});

// Define the interface for infrastructure configuration
interface IInfrastructureConfig {
  nodeVersion: string;
  typescriptVersion: string;
  nestjsVersion: string;
  postgresVersion: string;
  kafkaVersion: string;
  dockerVersion: string;
  kubernetesVersion: string;
}

// Custom error for configuration issues
class ConfigurationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigurationError';
  }
}

// Function to generate Infrastructure as Code
function generateIaC(config: IInfrastructureConfig): string {
  // Step 1: Validate the configuration
  const validation = InfrastructureConfigSchema.safeParse(config);
  if (!validation.success) {
    throw new ConfigurationError('Invalid configuration: ' + validation.error.message);
  }

  // Step 2: Generate Dockerfile
  const dockerfile = `FROM node:${config.nodeVersion}
WORKDIR /app
COPY . .
RUN npm install
CMD ["npm", "start"]`;

  // Step 3: Create Kubernetes deployment and service YAML
  const kubernetesDeployment = `apiVersion: apps/v1
kind: Deployment
metadata:
  name: my-app
spec:
  replicas: 3
  selector:
    matchLabels:
      app: my-app
  template:
    metadata:
      labels:
        app: my-app
    spec:
      containers:
      - name: my-app
        image: my-app-image
        ports:
        - containerPort: 3000`;

  const kubernetesService = `apiVersion: v1
kind: Service
metadata:
  name: my-app-service
spec:
  selector:
    app: my-app
  ports:
    - protocol: TCP
      port: 80
      targetPort: 3000`;

  // Step 4: Configure PostgreSQL database
  const postgresConfig = `CREATE DATABASE mydb;
CREATE USER myuser WITH ENCRYPTED PASSWORD 'mypassword';
GRANT ALL PRIVILEGES ON DATABASE mydb TO myuser;`;

  // Step 5: Set up Kafka topics
  const kafkaConfig = `kafka-topics --create --topic my-topic --bootstrap-server localhost:9092 --replication-factor 1 --partitions 1`;

  // Step 6: Integrate observability tools
  const observabilityConfig = `# Example observability configuration
logging:
  level: INFO
monitoring:
  enabled: true`;

  // Step 7: Ensure security best practices
  const securityConfig = `# Example security configuration
secrets:
  - name: db-password
    valueFrom:
      secretKeyRef:
        name: db-secrets
        key: password
encryption:
  enabled: true`;

  // Combine all configurations into a single IaC output
  return [
    'Dockerfile:', dockerfile,
    'Kubernetes Deployment:', kubernetesDeployment,
    'Kubernetes Service:', kubernetesService,
    'PostgreSQL Config:', postgresConfig,
    'Kafka Config:', kafkaConfig,
    'Observability Config:', observabilityConfig,
    'Security Config:', securityConfig
  ].join('\n\n');
}

