export class CPFValidator {
  /**
   * Valida se um CPF é válido.
   * @param cpf - CPF a ser validado
   * @returns true se o CPF for válido, caso contrário, false
   */
  public static isValid(cpf: string): boolean {
    const cleanCPF = cpf.replace(/[.-]/g, '');
    if (!/^[0-9]{11}$/.test(cleanCPF)) return false;

    const digits = cleanCPF.split('').map(Number);
    if (new Set(digits).size === 1) return false; // CPF com todos os dígitos iguais

    const calculateCheckDigit = (base: number[]): number => {
      const sum = base.reduce((acc, digit, index) => acc + digit * (base.length + 1 - index), 0);
      const remainder = (sum * 10) % 11;
      return remainder === 10 ? 0 : remainder;
    };

    const firstCheckDigit = calculateCheckDigit(digits.slice(0, 9));
    const secondCheckDigit = calculateCheckDigit(digits.slice(0, 10));

    return firstCheckDigit === digits[9] && secondCheckDigit === digits[10];
  }
}

