  public execute(dto: CreateTaskDTO): Task {
    this.validate(dto);
    const category = this.repository.findCategoryById(dto.categoryId);
    if (!category) {
      throw new UseCaseError('Category not found');
    }
    const task = Task.create({
      id: crypto.randomUUID(),
      title: dto.title,
      description: dto.description,
      category: category
    });
    this.repository.saveTask(task);
    return task;
  }

  private validate(dto: CreateTaskDTO): void {
    if (!dto.title || dto.title.trim().length === 0) {
      throw new UseCaseError('Title is required');
    }
    if (!dto.categoryId) {
      throw new UseCaseError('Category ID is required');
    }
  }
}

type Task = {
  id: string;
  title: string;
  completed: boolean;
  category: string;
};

class LocalStorageTaskRepository {
  private readonly storageKey = 'tasks';

  public getAllTasks(): Task[] {
    const tasksJson = localStorage.getItem(this.storageKey);
    if (!tasksJson) return [];
    try {
      return JSON.parse(tasksJson) as Task[];
    } catch (error) {
      console.error('Failed to parse tasks from localStorage', error);
      return [];
    }
  }

  public saveTask(task: Task): void {
    const tasks = this.getAllTasks();
    const taskIndex = tasks.findIndex(t => t.id === task.id);
    if (taskIndex > -1) {
      tasks[taskIndex] = task;
    } else {
      tasks.push(task);
    }
    localStorage.setItem(this.storageKey, JSON.stringify(tasks));
  }

  public deleteTask(taskId: string): void {
    const tasks = this.getAllTasks();
    const updatedTasks = tasks.filter(task => task.id !== taskId);
    localStorage.setItem(this.storageKey, JSON.stringify(updatedTasks));
  }

  public getTasksByCategory(category: string): Task[] {
    return this.getAllTasks().filter(task => task.category === category);
  }
}

