import { LocalStorageTaskRepository } from '../../../../src/infrastructure/storage/LocalStorageTaskRepository';
import { Task } from '../../../../src/domain/entities/Task';
import { describe, it, expect, beforeEach } from '@jest/globals';

const TASKS_KEY = 'tasks';

const mockTask: Task = {
  id: '1',
  title: 'Test Task',
  category: 'Test Category',
  completed: false
};

const clearLocalStorage = () => {
  localStorage.removeItem(TASKS_KEY);
};

describe('LocalStorageTaskRepository', () => {
  let repository: LocalStorageTaskRepository;

  beforeEach(() => {
    clearLocalStorage();
    repository = new LocalStorageTaskRepository();
  });

  it('should save a task to localStorage', () => {
    repository.save(mockTask);
    const storedTasks = JSON.parse(localStorage.getItem(TASKS_KEY) || '[]');
    expect(storedTasks).toHaveLength(1);
    expect(storedTasks[0]).toEqual(mockTask);
  });

  it('should retrieve tasks from localStorage', () => {
    localStorage.setItem(TASKS_KEY, JSON.stringify([mockTask]));
    const tasks = repository.getAll();
    expect(tasks).toHaveLength(1);
    expect(tasks[0]).toEqual(mockTask);
  });

  it('should remove a task from localStorage', () => {
    repository.save(mockTask);
    repository.remove(mockTask.id);
    const storedTasks = JSON.parse(localStorage.getItem(TASKS_KEY) || '[]');
    expect(storedTasks).toHaveLength(0);
  });
});

import { describe, it, expect } from '@jest/globals';
import { CreateTaskUseCase } from '../../../src/application/use-cases/CreateTaskUseCase';
